-- MTH 122 (Elementary Mathematics III, UNN) practice questions for the CBT feature.
-- 300 questions across 14 topics, grounded in the official UNN
-- Mathematics department textbook -- Amazigo et al., "Introductory University
-- Mathematics 3: Analytic Geometry, Vectors and Elementary Dynamics" -- and
-- scoped strictly to the official UNN MTH 122 course outline, whose 14 topics
-- map onto the textbook's chapters as follows:
--
--   Ch 1-2  The Straight Line, Coordinate Geometry of the Circle
--             -> two-dimensional coordinate geometry; straight lines; circles
--   Ch 3-4  Conic Sections, Applications and General Equations of the Conics
--             -> parabolas, ellipses, hyperbolas; tangents and normals
--   Ch 5    Vectors
--             -> geometric representation in 1-3 dimensions, components,
--                direction cosines; addition and scalar multiplication;
--                linear independence; scalar and vector products;
--                differentiation and integration with respect to a scalar
--   Ch 6    Kinematics of a Particle
--             -> kinematics; components of velocity and acceleration in a plane
--   Ch 7    Dynamics of a Particle
--             -> force and momentum; Newton's laws; motion under gravity;
--                projectile motion; elastic strings; the simple pendulum;
--                impulse; impact of two smooth elastic spheres; direct and
--                oblique impacts
--
-- Every numeric answer is recomputed from scratch with sympy and compared
-- symbolically against the stated key before being allowed into the bank, and
-- every explanation is a genuine step-by-step derivation rather than a bare
-- restatement of the answer.
--
-- Conventions carried over from the MTH 121 bank:
--   * LaTeX is used ONLY for genuine mathematical notation ($...$-delimited);
--     ordinary prose stays plain text rather than being force-wrapped.
--   * Question stems never name the technique to apply -- selecting the right
--     method is part of what is being tested.
--   * Distractors are plausible and of comparable length to the correct
--     answer, so the key cannot be picked out by shape alone.
--   * Correct answers are spread across A/B/C/D rather than always sitting in
--     one position.
--   * Where gravity is needed, its value is stated in the question, so no
--     answer depends on an unstated convention for g.
--
-- cbt_questions has no course_code column, so the MTH 122 link lives in
-- subject_name. is_general = false and faculty is pinned to 'Faculty of
-- Physical Sciences' so only students in that faculty see this paper.

delete from public.cbt_questions where subject_id = 'mth-122-vectors-geometry-dynamics';

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general)
values
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the magnitude of the vector $\mathbf{a} = 3\mathbf{i} - 4\mathbf{j}$.', '["$5$", "$7$", "$\\sqrt{7}$", "$1$"]'::jsonb, 0, 'The magnitude is $|\mathbf{a}| = \sqrt{3^{2}+(-4)^{2}} = \sqrt{9+16} = \sqrt{25} = 5$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the magnitude of the vector $\mathbf{a} = 2\mathbf{i} + 3\mathbf{j} + 6\mathbf{k}$.', '["$7$", "$11$", "$\\sqrt{11}$", "$36$"]'::jsonb, 0, '$|\mathbf{a}| = \sqrt{2^{2}+3^{2}+6^{2}} = \sqrt{4+9+36} = \sqrt{49} = 7$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the unit vector in the direction of $\mathbf{a} = \mathbf{i} + 2\mathbf{j} + 2\mathbf{k}$.', '["$\\frac{1}{9}(\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k})$", "$\\frac{1}{5}(\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k})$", "$3(\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k})$", "$\\frac{1}{3}(\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k})$"]'::jsonb, 3, 'First $|\mathbf{a}| = \sqrt{1^{2}+2^{2}+2^{2}} = \sqrt{9} = 3$. The unit vector is $\hat{\mathbf{a}} = \dfrac{\mathbf{a}}{|\mathbf{a}|} = \dfrac{1}{3}(\mathbf{i}+2\mathbf{j}+2\mathbf{k})$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The direction cosines of the vector $\mathbf{a} = \mathbf{i} + 2\mathbf{j} + 2\mathbf{k}$ are:', '["$1, 2, 2$", "$\\frac{1}{2}, 1, 1$", "$\\frac{1}{3}, \\frac{2}{3}, \\frac{2}{3}$", "$\\frac{1}{9}, \\frac{2}{9}, \\frac{2}{9}$"]'::jsonb, 2, 'The direction cosines are the components of the unit vector: $l = \dfrac{a_1}{|\mathbf{a}|}$, $m = \dfrac{a_2}{|\mathbf{a}|}$, $n = \dfrac{a_3}{|\mathbf{a}|}$. With $|\mathbf{a}| = 3$: $l = \dfrac{1}{3}$, $m = \dfrac{2}{3}$, $n = \dfrac{2}{3}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $l$, $m$ and $n$ are the direction cosines of a vector, then $l^2 + m^2 + n^2$ equals:', '["the square of the magnitude", "$1$", "$0$", "the magnitude of the vector"]'::jsonb, 1, 'The direction cosines are the components of a unit vector, so their squares sum to the square of that unit vector''s magnitude: $l^{2}+m^{2}+n^{2} = 1$ for every vector.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given the points $A(1, 2, 3)$ and $B(4, 6, 3)$, find the vector $\overrightarrow{AB}$.', '["$5\\mathbf{i} + 8\\mathbf{j} + 6\\mathbf{k}$", "$-3\\mathbf{i} - 4\\mathbf{j}$", "$3\\mathbf{i} + 4\\mathbf{j} + 6\\mathbf{k}$", "$3\\mathbf{i} + 4\\mathbf{j}$"]'::jsonb, 3, '$\overrightarrow{AB} = \mathbf{b} - \mathbf{a} = (4-1)\mathbf{i} + (6-2)\mathbf{j} + (3-3)\mathbf{k} = 3\mathbf{i} + 4\mathbf{j}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 2\mathbf{i} - \mathbf{j} + 3\mathbf{k}$ and $\mathbf{b} = \mathbf{i} + 4\mathbf{j} - 2\mathbf{k}$, find $\mathbf{a} + \mathbf{b}$.', '["$\\mathbf{i} - 5\\mathbf{j} + 5\\mathbf{k}$", "$3\\mathbf{i} + 3\\mathbf{j} + 5\\mathbf{k}$", "$2\\mathbf{i} - 4\\mathbf{j} - 6\\mathbf{k}$", "$3\\mathbf{i} + 3\\mathbf{j} + \\mathbf{k}$"]'::jsonb, 3, 'Add corresponding components: $(2+1)\mathbf{i} + (-1+4)\mathbf{j} + (3-2)\mathbf{k} = 3\mathbf{i} + 3\mathbf{j} + \mathbf{k}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 2\mathbf{i} - \mathbf{j} + 3\mathbf{k}$ and $\mathbf{b} = \mathbf{i} + 4\mathbf{j} - 2\mathbf{k}$, find $\mathbf{a} - \mathbf{b}$.', '["$3\\mathbf{i} + 3\\mathbf{j} + \\mathbf{k}$", "$\\mathbf{i} + 5\\mathbf{j} - 5\\mathbf{k}$", "$-\\mathbf{i} - 5\\mathbf{j} + \\mathbf{k}$", "$\\mathbf{i} - 5\\mathbf{j} + 5\\mathbf{k}$"]'::jsonb, 3, 'Subtract corresponding components: $(2-1)\mathbf{i} + (-1-4)\mathbf{j} + (3-(-2))\mathbf{k} = \mathbf{i} - 5\mathbf{j} + 5\mathbf{k}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 2\mathbf{i} - \mathbf{j} + 3\mathbf{k}$ and $\mathbf{b} = \mathbf{i} + 4\mathbf{j} - 2\mathbf{k}$, find $3\mathbf{a} - 2\mathbf{b}$.', '["$6\\mathbf{i} - 3\\mathbf{j} + 9\\mathbf{k}$", "$4\\mathbf{i} - 11\\mathbf{j} + 13\\mathbf{k}$", "$8\\mathbf{i} + 5\\mathbf{j} + 5\\mathbf{k}$", "$4\\mathbf{i} + 11\\mathbf{j} + 13\\mathbf{k}$"]'::jsonb, 1, '$3\mathbf{a} = 6\mathbf{i} - 3\mathbf{j} + 9\mathbf{k}$ and $2\mathbf{b} = 2\mathbf{i} + 8\mathbf{j} - 4\mathbf{k}$. Subtracting: $(6-2)\mathbf{i} + (-3-8)\mathbf{j} + (9+4)\mathbf{k} = 4\mathbf{i} - 11\mathbf{j} + 13\mathbf{k}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Which statement correctly describes the vectors $\mathbf{a} = 2\mathbf{i} + 4\mathbf{j}$ and $\mathbf{b} = \mathbf{i} + 2\mathbf{j}$?', '["They are linearly independent, since neither is a scalar multiple of the other", "They are perpendicular, since their scalar product vanishes", "They are both unit vectors, since each has magnitude one", "They are linearly dependent, since one is a scalar multiple of the other"]'::jsonb, 3, '$\mathbf{a} = 2\mathbf{b}$, so one vector is a scalar multiple of the other. Two such vectors are parallel and therefore linearly dependent.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Which statement correctly describes the vectors $\mathbf{a} = \mathbf{i}$ and $\mathbf{b} = \mathbf{j}$?', '["They are linearly dependent, since both have magnitude one", "They are linearly dependent, since one is a scalar multiple of the other", "They are equal, since both are standard basis vectors", "They are linearly independent, since neither is a scalar multiple of the other"]'::jsonb, 3, 'No scalar $\lambda$ satisfies $\mathbf{i} = \lambda\mathbf{j}$, since the two point along different axes. Neither is a multiple of the other, so they are linearly independent.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $k$ are the vectors $\mathbf{a} = 3\mathbf{i} + k\mathbf{j}$ and $\mathbf{b} = 6\mathbf{i} + 10\mathbf{j}$ parallel?', '["$k = 5$", "$k = 20$", "$k = 2$", "$k = -5$"]'::jsonb, 0, 'Parallel vectors satisfy $\mathbf{a} = \lambda\mathbf{b}$. Comparing $\mathbf{i}$ components, $3 = 6\lambda$ so $\lambda = \dfrac{1}{2}$. Comparing $\mathbf{j}$ components, $k = 10\lambda = 10 \cdot \dfrac{1}{2} = 5$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = \mathbf{i} + 2\mathbf{j} + 3\mathbf{k}$ and $\mathbf{b} = 4\mathbf{i} - 5\mathbf{j} + 6\mathbf{k}$, find $\mathbf{a} \cdot \mathbf{b}$.', '["$-12$", "$4$", "$12$", "$32$"]'::jsonb, 2, 'Multiply corresponding components and add: $\mathbf{a} \cdot \mathbf{b} = (1)(4) + (2)(-5) + (3)(6) = 4 - 10 + 18 = 12$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 2\mathbf{i} + 3\mathbf{j}$ and $\mathbf{b} = 3\mathbf{i} - 2\mathbf{j}$, what can be concluded about these vectors?', '["They are parallel, since their scalar product is zero", "They are perpendicular, since their vector product is zero", "They are identical, since they have equal magnitudes", "They are perpendicular, since their scalar product is zero"]'::jsonb, 3, '$\mathbf{a} \cdot \mathbf{b} = (2)(3) + (3)(-2) = 6 - 6 = 0$. A vanishing scalar product between two non-zero vectors means the angle between them is $90^{\circ}$, so they are perpendicular.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the angle between the vectors $\mathbf{a} = \mathbf{i}$ and $\mathbf{b} = \mathbf{i} + \mathbf{j}$.', '["$30^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$", "$45^{\\circ}$"]'::jsonb, 3, '$\cos\theta = \dfrac{\mathbf{a}\cdot\mathbf{b}}{|\mathbf{a}||\mathbf{b}|} = \dfrac{1}{(1)(\sqrt{2})} = \dfrac{1}{\sqrt{2}}$, so $\theta = 45^{\circ}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For what value of $k$ are $\mathbf{a} = 2\mathbf{i} + k\mathbf{j} + \mathbf{k}$ and $\mathbf{b} = 3\mathbf{i} - \mathbf{j} + 4\mathbf{k}$ perpendicular?', '["$k = -10$", "$k = 2$", "$k = 6$", "$k = 10$"]'::jsonb, 3, 'Perpendicular vectors have zero scalar product: $(2)(3) + (k)(-1) + (1)(4) = 0$, i.e. $6 - k + 4 = 0$, giving $k = 10$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\mathbf{i} \times \mathbf{j}$.', '["$1$", "$\\mathbf{k}$", "$-\\mathbf{k}$", "$0$"]'::jsonb, 1, 'By the right-handed convention for the standard basis vectors, $\mathbf{i} \times \mathbf{j} = \mathbf{k}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 2\mathbf{i} + \mathbf{j} - \mathbf{k}$ and $\mathbf{b} = \mathbf{i} + 3\mathbf{j} + 2\mathbf{k}$, find $\mathbf{a} \times \mathbf{b}$.', '["$2\\mathbf{i} + 3\\mathbf{j} - 2\\mathbf{k}$", "$5\\mathbf{i} - 5\\mathbf{j} + 5\\mathbf{k}$", "$-5\\mathbf{i} + 5\\mathbf{j} - 5\\mathbf{k}$", "$5\\mathbf{i} + 5\\mathbf{j} + 5\\mathbf{k}$"]'::jsonb, 1, 'Expanding the determinant, the $\mathbf{i}$ component is $(1)(2)-(-1)(3) = 5$, the $\mathbf{j}$ component is $-[(2)(2)-(-1)(1)] = -5$, and the $\mathbf{k}$ component is $(2)(3)-(1)(1) = 5$. So $\mathbf{a} \times \mathbf{b} = 5\mathbf{i} - 5\mathbf{j} + 5\mathbf{k}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If two non-zero vectors $\mathbf{a}$ and $\mathbf{b}$ satisfy $\mathbf{a} \times \mathbf{b} = \mathbf{0}$, then the vectors must be:', '["both of unit magnitude", "parallel to each other", "perpendicular to each other", "equal in magnitude but opposite in direction"]'::jsonb, 1, 'Since $|\mathbf{a} \times \mathbf{b}| = |\mathbf{a}||\mathbf{b}|\sin\theta$, a vanishing vector product between non-zero vectors forces $\sin\theta = 0$, i.e. $\theta = 0^{\circ}$ or $180^{\circ}$ -- the vectors are parallel.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the parallelogram whose adjacent sides are $\mathbf{a} = 3\mathbf{i}$ and $\mathbf{b} = 4\mathbf{j}$.', '["$5$", "$12$", "$7$", "$6$"]'::jsonb, 1, 'The area of the parallelogram equals $|\mathbf{a} \times \mathbf{b}|$. Here $\mathbf{a} \times \mathbf{b} = 12\mathbf{k}$, so the area is $12$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t) = t^2\mathbf{i} + 3t\mathbf{j} + \sin t\,\mathbf{k}$, find $\dfrac{d\mathbf{r}}{dt}$.', '["$2t\\mathbf{i} + 3t\\mathbf{j} - \\cos t\\,\\mathbf{k}$", "$2\\mathbf{i} + 3\\mathbf{j} - \\sin t\\,\\mathbf{k}$", "$t^2\\mathbf{i} + 3\\mathbf{j} + \\cos t\\,\\mathbf{k}$", "$2t\\mathbf{i} + 3\\mathbf{j} + \\cos t\\,\\mathbf{k}$"]'::jsonb, 3, 'Differentiate each component separately with respect to $t$: $\dfrac{d}{dt}(t^{2}) = 2t$, $\dfrac{d}{dt}(3t) = 3$, and $\dfrac{d}{dt}(\sin t) = \cos t$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t) = t^3\mathbf{i} + t^2\mathbf{j} + t\mathbf{k}$, evaluate $\dfrac{d\mathbf{r}}{dt}$ at $t = 1$.', '["$\\mathbf{i} + \\mathbf{j} + \\mathbf{k}$", "$6\\mathbf{i} + 2\\mathbf{j}$", "$3\\mathbf{i} + 2\\mathbf{j}$", "$3\\mathbf{i} + 2\\mathbf{j} + \\mathbf{k}$"]'::jsonb, 3, '$\dfrac{d\mathbf{r}}{dt} = 3t^{2}\mathbf{i} + 2t\mathbf{j} + \mathbf{k}$. Substituting $t=1$ gives $3\mathbf{i} + 2\mathbf{j} + \mathbf{k}$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{0}^{1} \left(2t\,\mathbf{i} + 3t^2\mathbf{j} + \mathbf{k}\right)\,dt$.', '["$\\mathbf{i} + \\mathbf{j}$", "$\\frac{1}{2}\\mathbf{i} + \\mathbf{j} + \\mathbf{k}$", "$\\mathbf{i} + \\mathbf{j} + \\mathbf{k}$", "$2\\mathbf{i} + 3\\mathbf{j} + \\mathbf{k}$"]'::jsonb, 2, 'Integrate each component over $[0,1]$: $\int_0^1 2t\,dt = 1$, $\int_0^1 3t^{2}\,dt = 1$, and $\int_0^1 1\,dt = 1$. So the result is $\mathbf{i} + \mathbf{j} + \mathbf{k}$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t) = t^2\mathbf{i} + t^3\mathbf{j}$, find $\dfrac{d^2\mathbf{r}}{dt^2}$.', '["$2\\mathbf{i} + 6t\\mathbf{j}$", "$2t\\mathbf{i} + 3t^2\\mathbf{j}$", "$2\\mathbf{i} + 3t\\mathbf{j}$", "$6t\\mathbf{j}$"]'::jsonb, 0, 'First $\dfrac{d\mathbf{r}}{dt} = 2t\mathbf{i} + 3t^{2}\mathbf{j}$. Differentiating again gives $\dfrac{d^{2}\mathbf{r}}{dt^{2}} = 2\mathbf{i} + 6t\mathbf{j}$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $A(1, 2)$ and $B(4, 6)$.', '["$7$", "$\\sqrt{7}$", "$25$", "$5$"]'::jsonb, 3, '$d = \sqrt{(x_2-x_1)^{2} + (y_2-y_1)^{2}} = \sqrt{(4-1)^{2}+(6-2)^{2}} = \sqrt{9+16} = \sqrt{25} = 5$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the midpoint of the line segment joining $A(2, 3)$ and $B(8, 7)$.', '["$(5, 5)$", "$(10, 10)$", "$(3, 2)$", "$(6, 4)$"]'::jsonb, 0, 'The midpoint is $\left(\dfrac{x_1+x_2}{2}, \dfrac{y_1+y_2}{2}\right) = \left(\dfrac{2+8}{2}, \dfrac{3+7}{2}\right) = (5, 5)$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the line joining $A(1, 3)$ and $B(5, 7)$.', '["$2$", "$\\frac{1}{2}$", "$4$", "$1$"]'::jsonb, 3, 'The gradient is $m = \dfrac{y_2-y_1}{x_2-x_1} = \dfrac{7-3}{5-1} = \dfrac{4}{4} = 1$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the straight line through the point $(2, 5)$ with gradient $3$.', '["$y = 3x + 1$", "$y = 3x - 5$", "$y = 2x + 5$", "$y = 3x - 1$"]'::jsonb, 3, 'Using $y - y_1 = m(x - x_1)$: $y - 5 = 3(x - 2)$, so $y - 5 = 3x - 6$, giving $y = 3x - 1$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A line has gradient $\frac{2}{3}$. What is the gradient of any line perpendicular to it?', '["$\\frac{3}{2}$", "$-\\frac{2}{3}$", "$\\frac{2}{3}$", "$-\\frac{3}{2}$"]'::jsonb, 3, 'For perpendicular lines the product of the gradients is $-1$, so the required gradient is $m_2 = -\dfrac{1}{m_1} = -\dfrac{1}{2/3} = -\dfrac{3}{2}$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the perpendicular distance from the point $(1, 2)$ to the line $3x + 4y - 5 = 0$.', '["$6$", "$\\frac{6}{25}$", "$\\frac{6}{5}$", "$\\frac{5}{6}$"]'::jsonb, 2, 'The distance from $(x_0,y_0)$ to $ax+by+c=0$ is $\dfrac{|ax_0+by_0+c|}{\sqrt{a^{2}+b^{2}}} = \dfrac{|3(1)+4(2)-5|}{\sqrt{9+16}} = \dfrac{6}{5}$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the triangle with vertices $(0, 0)$, $(4, 0)$ and $(0, 3)$.', '["$12$", "$7$", "$5$", "$6$"]'::jsonb, 3, 'Using $\text{Area} = \dfrac{1}{2}|x_1(y_2-y_3) + x_2(y_3-y_1) + x_3(y_1-y_2)|$: $\dfrac{1}{2}|0(0-3) + 4(3-0) + 0(0-0)| = \dfrac{1}{2}(12) = 6$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the centre and radius of the circle $(x - 2)^2 + (y + 3)^2 = 25$.', '["centre $(2, -3)$, radius $25$", "centre $(2, 3)$, radius $5$", "centre $(2, -3)$, radius $5$", "centre $(-2, 3)$, radius $5$"]'::jsonb, 2, 'Comparing with the standard form $(x-a)^{2}+(y-b)^{2}=r^{2}$: $a=2$, $b=-3$ and $r^{2}=25$, so the centre is $(2,-3)$ and the radius is $5$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the centre and radius of the circle $x^2 + y^2 - 4x + 6y - 12 = 0$.', '["centre $(4, -6)$, radius $5$", "centre $(2, -3)$, radius $\\sqrt{12}$", "centre $(2, -3)$, radius $5$", "centre $(-2, 3)$, radius $5$"]'::jsonb, 2, 'For $x^{2}+y^{2}+2gx+2fy+c=0$ the centre is $(-g,-f)$ and the radius is $\sqrt{g^{2}+f^{2}-c}$. Here $2g=-4$ so $g=-2$; $2f=6$ so $f=3$; $c=-12$. The centre is $(2,-3)$ and the radius is $\sqrt{4+9+12} = \sqrt{25} = 5$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the circle with centre $(1, -2)$ and radius $3$.', '["$(x - 1)^2 + (y + 2)^2 = 3$", "$(x - 1)^2 + (y - 2)^2 = 9$", "$(x - 1)^2 + (y + 2)^2 = 9$", "$(x + 1)^2 + (y - 2)^2 = 9$"]'::jsonb, 2, 'Substituting $a=1$, $b=-2$ and $r=3$ into $(x-a)^{2}+(y-b)^{2}=r^{2}$ gives $(x-1)^{2}+(y+2)^{2}=9$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A circle has the segment joining $(0, 0)$ and $(4, 6)$ as a diameter. Find its centre and radius.', '["centre $(2, 3)$, radius $13$", "centre $(4, 6)$, radius $\\sqrt{13}$", "centre $(2, 3)$, radius $\\sqrt{26}$", "centre $(2, 3)$, radius $\\sqrt{13}$"]'::jsonb, 3, 'The centre is the midpoint of the diameter: $\left(\dfrac{0+4}{2},\dfrac{0+6}{2}\right) = (2,3)$. The radius is the distance from the centre to an endpoint: $\sqrt{(4-2)^{2}+(6-3)^{2}} = \sqrt{4+9} = \sqrt{13}$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the length of the tangent drawn from the point $(5, 0)$ to the circle $x^2 + y^2 = 9$.', '["$4$", "$5$", "$3$", "$\\sqrt{34}$"]'::jsonb, 0, 'The tangent length from $(x_0,y_0)$ to $x^{2}+y^{2}=r^{2}$ is $\sqrt{x_0^{2}+y_0^{2}-r^{2}} = \sqrt{25+0-9} = \sqrt{16} = 4$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the parabola $y^2 = 12x$, find the coordinates of the focus.', '["$(3, 0)$", "$(0, 3)$", "$(12, 0)$", "$(-3, 0)$"]'::jsonb, 0, 'Comparing $y^{2}=12x$ with the standard form $y^{2}=4ax$ gives $4a=12$, so $a=3$. The focus of $y^{2}=4ax$ is at $(a,0)$, which is $(3,0)$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the parabola $y^2 = 12x$, find the equation of the directrix.', '["$y = -3$", "$x = -12$", "$x = -3$", "$x = 3$"]'::jsonb, 2, 'With $4a=12$ we have $a=3$. The directrix of $y^{2}=4ax$ is the line $x=-a$, so here it is $x=-3$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{25} + \dfrac{y^2}{9} = 1$, find the eccentricity.', '["$\\frac{4}{5}$", "$\\frac{3}{5}$", "$\\frac{5}{4}$", "$\\frac{9}{25}$"]'::jsonb, 0, 'Here $a^{2}=25$ and $b^{2}=9$, so $a=5$ and $b=3$. The eccentricity satisfies $b^{2}=a^{2}(1-e^{2})$, giving $e = \sqrt{1-\dfrac{b^{2}}{a^{2}}} = \sqrt{1-\dfrac{9}{25}} = \sqrt{\dfrac{16}{25}} = \dfrac{4}{5}$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{25} + \dfrac{y^2}{9} = 1$, find the coordinates of the foci.', '["$(\\pm 5, 0)$", "$(\\pm 3, 0)$", "$(\\pm 4, 0)$", "$(0, \\pm 4)$"]'::jsonb, 2, 'With $a=5$ and $e=\dfrac{4}{5}$, the foci lie at $(\pm ae, 0)$. Since $ae = 5 \cdot \dfrac{4}{5} = 4$, the foci are $(\pm 4, 0)$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{25} + \dfrac{y^2}{9} = 1$, find the length of the major axis.', '["$6$", "$25$", "$10$", "$5$"]'::jsonb, 2, 'Since $a^{2}=25 > b^{2}=9$, the major axis lies along the $x$-axis and has length $2a = 2(5) = 10$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the hyperbola $\dfrac{x^2}{16} - \dfrac{y^2}{9} = 1$, find the eccentricity.', '["$\\frac{3}{4}$", "$\\frac{25}{16}$", "$\\frac{5}{4}$", "$\\frac{4}{5}$"]'::jsonb, 2, 'For a hyperbola, $b^{2}=a^{2}(e^{2}-1)$, so $e = \sqrt{1+\dfrac{b^{2}}{a^{2}}}$. With $a^{2}=16$ and $b^{2}=9$: $e = \sqrt{1+\dfrac{9}{16}} = \sqrt{\dfrac{25}{16}} = \dfrac{5}{4}$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the hyperbola $\dfrac{x^2}{16} - \dfrac{y^2}{9} = 1$, find the equations of the asymptotes.', '["$y = \\pm\\frac{4}{3}x$", "$y = \\pm\\frac{9}{16}x$", "$y = \\pm\\frac{5}{4}x$", "$y = \\pm\\frac{3}{4}x$"]'::jsonb, 3, 'The asymptotes of $\dfrac{x^{2}}{a^{2}}-\dfrac{y^{2}}{b^{2}}=1$ are $y = \pm\dfrac{b}{a}x$. With $a=4$ and $b=3$, they are $y = \pm\dfrac{3}{4}x$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to the curve $y = x^2$ at the point $(2, 4)$.', '["$y = 4x - 4$", "$y = 4x + 4$", "$y = 2x$", "$y = 4x - 2$"]'::jsonb, 0, '$\dfrac{dy}{dx} = 2x$, so at $x=2$ the gradient is $4$. Using $y-y_1=m(x-x_1)$: $y-4 = 4(x-2)$, which simplifies to $y = 4x-4$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the normal to the curve $y = x^2$ at the point $(2, 4)$.', '["$y = -\\frac{1}{4}x + \\frac{9}{2}$", "$y = -4x + 12$", "$y = \\frac{1}{4}x + \\frac{7}{2}$", "$y = -\\frac{1}{4}x + 4$"]'::jsonb, 0, 'The tangent gradient at $(2,4)$ is $4$, so the normal gradient is $-\dfrac{1}{4}$. Then $y-4 = -\dfrac{1}{4}(x-2)$, giving $y = -\dfrac{1}{4}x + \dfrac{1}{2} + 4 = -\dfrac{1}{4}x + \dfrac{9}{2}$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to the circle $x^2 + y^2 = 25$ at the point $(3, 4)$.', '["$3x - 4y = 25$", "$3x + 4y = 5$", "$3x + 4y = 25$", "$4x + 3y = 25$"]'::jsonb, 2, 'The tangent to $x^{2}+y^{2}=r^{2}$ at the point $(x_1,y_1)$ on the circle is $xx_1 + yy_1 = r^{2}$. With $(x_1,y_1)=(3,4)$ and $r^{2}=25$: $3x+4y=25$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the tangent to the parabola $y^2 = 8x$ at the point $(2, 4)$.', '["$4$", "$1$", "$2$", "$\\frac{1}{2}$"]'::jsonb, 1, 'Differentiating $y^{2}=8x$ implicitly gives $2y\dfrac{dy}{dx}=8$, so $\dfrac{dy}{dx} = \dfrac{4}{y}$. At the point $(2,4)$ this is $\dfrac{4}{4} = 1$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The normal to a circle at any point on its circumference always passes through:', '["the point where the circle meets the x-axis", "the midpoint of the circle''s vertical diameter", "the centre of the circle", "the origin of the coordinate system"]'::jsonb, 2, 'The tangent at a point on a circle is perpendicular to the radius drawn to that point. The normal is perpendicular to the tangent, so it lies along that radius and therefore passes through the centre.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves along a straight line with displacement $s = t^3 - 6t^2 + 9t$ metres. Find its velocity at $t = 4$ s.', '["$12$ m/s", "$4$ m/s", "$9$ m/s", "$-3$ m/s"]'::jsonb, 2, 'Velocity is $v = \dfrac{ds}{dt} = 3t^{2}-12t+9$. At $t=4$: $v = 3(16)-12(4)+9 = 48-48+9 = 9$ m/s.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves along a straight line with displacement $s = t^3 - 6t^2 + 9t$ metres. Find its acceleration at $t = 4$ s.', '["$-12$ m/s$^2$", "$9$ m/s$^2$", "$6$ m/s$^2$", "$12$ m/s$^2$"]'::jsonb, 3, 'Acceleration is $a = \dfrac{d^{2}s}{dt^{2}} = 6t-12$. At $t=4$: $a = 24-12 = 12$ m/s$^{2}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves with displacement $s = t^3 - 6t^2 + 9t$ metres. At what times is the particle momentarily at rest?', '["$t = 2$ s only", "$t = 1$ s and $t = 9$ s", "$t = 1$ s and $t = 3$ s", "$t = 0$ s and $t = 3$ s"]'::jsonb, 2, 'The particle is at rest when $v = 3t^{2}-12t+9 = 0$, i.e. $3(t-1)(t-3)=0$, which gives $t=1$ s and $t=3$ s.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body starts with velocity $5$ m/s and moves with constant acceleration $3$ m/s$^2$. Find its velocity after $4$ s.', '["$20$ m/s", "$8$ m/s", "$17$ m/s", "$12$ m/s"]'::jsonb, 2, 'Using $v = u + at$ with $u=5$, $a=3$ and $t=4$: $v = 5 + 3(4) = 5+12 = 17$ m/s.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body starts with velocity $5$ m/s and moves with constant acceleration $3$ m/s$^2$. Find the distance covered in $4$ s.', '["$44$ m", "$68$ m", "$24$ m", "$32$ m"]'::jsonb, 0, 'Using $s = ut + \dfrac{1}{2}at^{2}$: $s = 5(4) + \dfrac{1}{2}(3)(16) = 20 + 24 = 44$ m.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A car travelling at $20$ m/s decelerates uniformly at $5$ m/s$^2$. How far does it travel before coming to rest?', '["$80$ m", "$20$ m", "$4$ m", "$40$ m"]'::jsonb, 3, 'Using $v^{2} = u^{2} + 2as$ with $v=0$, $u=20$ and $a=-5$: $0 = 400 - 10s$, so $s = 40$ m.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves in a plane with position vector $\mathbf{r} = 3t^2\mathbf{i} + 2t^3\mathbf{j}$. Find its velocity at $t = 1$.', '["$6\\mathbf{i} + 6\\mathbf{j}$", "$3\\mathbf{i} + 2\\mathbf{j}$", "$6\\mathbf{i} + 12\\mathbf{j}$", "$6\\mathbf{i} + 3\\mathbf{j}$"]'::jsonb, 0, 'Velocity is $\mathbf{v} = \dfrac{d\mathbf{r}}{dt} = 6t\mathbf{i} + 6t^{2}\mathbf{j}$. At $t=1$: $\mathbf{v} = 6\mathbf{i} + 6\mathbf{j}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves in a plane with position vector $\mathbf{r} = 3t^2\mathbf{i} + 2t^3\mathbf{j}$. Find its acceleration at $t = 1$.', '["$6\\mathbf{i} + 6\\mathbf{j}$", "$12\\mathbf{i} + 6\\mathbf{j}$", "$6\\mathbf{j}$", "$6\\mathbf{i} + 12\\mathbf{j}$"]'::jsonb, 3, '$\mathbf{v} = 6t\mathbf{i} + 6t^{2}\mathbf{j}$, so $\mathbf{a} = \dfrac{d\mathbf{v}}{dt} = 6\mathbf{i} + 12t\mathbf{j}$. At $t=1$: $\mathbf{a} = 6\mathbf{i} + 12\mathbf{j}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle has velocity $\mathbf{v} = 6\mathbf{i} + 6\mathbf{j}$ m/s. Find its speed.', '["$72$ m/s", "$6\\sqrt{2}$ m/s", "$12$ m/s", "$6$ m/s"]'::jsonb, 1, 'Speed is the magnitude of the velocity: $|\mathbf{v}| = \sqrt{6^{2}+6^{2}} = \sqrt{72} = 6\sqrt{2}$ m/s.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves in a circle of radius $3$ m with constant angular speed $4$ rad/s. Find its linear speed.', '["$0.75$ m/s", "$7$ m/s", "$12$ m/s", "$48$ m/s"]'::jsonb, 2, 'For circular motion the linear speed is $v = r\omega = (3)(4) = 12$ m/s.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves in a circle of radius $3$ m with constant angular speed $4$ rad/s. Find the magnitude of its acceleration.', '["$48$ m/s$^2$", "$12$ m/s$^2$", "$36$ m/s$^2$", "$16$ m/s$^2$"]'::jsonb, 0, 'For uniform circular motion the acceleration is directed toward the centre with magnitude $a = r\omega^{2} = (3)(4)^{2} = 48$ m/s$^{2}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a particle moving along a curved path, the direction of the instantaneous velocity vector at any point is:', '["along the normal to the path at that point", "directed toward the centre of curvature of the path", "always parallel to the acceleration vector", "along the tangent to the path at that point"]'::jsonb, 3, 'Velocity is $\dfrac{d\mathbf{r}}{dt}$, the limit of a chord direction as the time interval shrinks to zero. That limiting direction is the tangent to the path, so the velocity is always tangential.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A force acts on a body of mass $5$ kg, giving it an acceleration of $3$ m/s$^2$. Find the magnitude of the force.', '["$45$ N", "$15$ N", "$8$ N", "$1.67$ N"]'::jsonb, 1, 'By Newton''s second law, $F = ma = (5)(3) = 15$ N.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the momentum of a body of mass $4$ kg moving with velocity $12$ m/s.', '["$48$ kg m/s", "$3$ kg m/s", "$16$ kg m/s", "$24$ kg m/s"]'::jsonb, 0, 'Momentum is $p = mv = (4)(12) = 48$ kg m/s.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Newton''s first law of motion states that a body remains at rest, or continues to move with uniform velocity in a straight line, unless:', '["it is acted upon by an external resultant force", "its mass is changed by an external agent", "its momentum is equal to zero at that instant", "it is moving through a perfectly smooth medium"]'::jsonb, 0, 'Newton''s first law (the law of inertia) says a body''s state of rest or uniform motion persists unless a net external force acts on it to change that state.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Newton''s third law of motion states that:', '["the acceleration produced is proportional to the applied force", "a body continues in its state of rest unless acted upon by a force", "the total momentum of an isolated system is always conserved", "to every action there is an equal and opposite reaction"]'::jsonb, 3, 'Newton''s third law states that when one body exerts a force on a second, the second exerts a force of equal magnitude and opposite direction on the first.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A horizontal force of $50$ N acts on a $10$ kg block against a frictional force of $20$ N. Find the acceleration of the block.', '["$3$ m/s$^2$", "$5$ m/s$^2$", "$7$ m/s$^2$", "$2$ m/s$^2$"]'::jsonb, 0, 'The resultant force is $50 - 20 = 30$ N. By Newton''s second law, $a = \dfrac{F}{m} = \dfrac{30}{10} = 3$ m/s$^{2}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Taking $g = 10$ m/s$^2$, find the weight of a body of mass $8$ kg.', '["$8$ N", "$0.8$ N", "$18$ N", "$80$ N"]'::jsonb, 3, 'Weight is the gravitational force on the body: $W = mg = (8)(10) = 80$ N.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball is projected vertically upward with speed $20$ m/s. Taking $g = 10$ m/s$^2$, find the maximum height reached.', '["$40$ m", "$10$ m", "$2$ m", "$20$ m"]'::jsonb, 3, 'At the highest point $v=0$. Using $v^{2} = u^{2} - 2gh$: $0 = 400 - 20h$, so $h = 20$ m.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball is projected vertically upward with speed $20$ m/s. Taking $g = 10$ m/s$^2$, find the total time before it returns to the point of projection.', '["$1$ s", "$4$ s", "$2$ s", "$8$ s"]'::jsonb, 1, 'The time to reach the top is $\dfrac{u}{g} = \dfrac{20}{10} = 2$ s, and by symmetry the descent takes the same time. The total time is $2 \times 2 = 4$ s.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A projectile is launched with speed $20$ m/s at $45^{\circ}$ to the horizontal. Taking $g = 10$ m/s$^2$, find its horizontal range.', '["$40$ m", "$20$ m", "$80$ m", "$10$ m"]'::jsonb, 0, 'The range is $R = \dfrac{u^{2}\sin 2\theta}{g}$. With $u=20$, $\theta=45^{\circ}$ (so $\sin 90^{\circ}=1$) and $g=10$: $R = \dfrac{400}{10} = 40$ m.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a projectile launched at a fixed speed over level ground, the horizontal range is greatest when the angle of projection is:', '["$30^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$", "$45^{\\circ}$"]'::jsonb, 3, 'Since $R = \dfrac{u^{2}\sin 2\theta}{g}$, the range is greatest when $\sin 2\theta$ is greatest, i.e. $\sin 2\theta = 1$, giving $2\theta = 90^{\circ}$ and $\theta = 45^{\circ}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Neglecting air resistance, the horizontal component of a projectile''s velocity during its flight:', '["increases steadily as the projectile falls", "decreases steadily until it reaches zero at the highest point", "changes direction at the highest point of the path", "remains constant throughout the motion"]'::jsonb, 3, 'Gravity acts vertically only, so there is no horizontal acceleration. The horizontal velocity component is therefore unchanged throughout the flight.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves so that its acceleration is always directed toward a fixed point and is proportional to its distance from that point. This motion is described by the equation:', '["$\\ddot{x} = -\\omega^2 x$", "$\\ddot{x} = \\omega^2 x$", "$\\ddot{x} = -\\omega^2 \\dot{x}$", "$\\dot{x} = -\\omega^2 x$"]'::jsonb, 0, 'Simple harmonic motion is defined by $\ddot{x} = -\omega^{2}x$: the acceleration is proportional to the displacement and the minus sign makes it always point back toward the fixed centre.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle performs simple harmonic motion with $\ddot{x} = -16x$. Find the period of the motion.', '["$\\frac{\\pi}{2}$ s", "$\\frac{\\pi}{4}$ s", "$2\\pi$ s", "$8\\pi$ s"]'::jsonb, 0, 'Comparing with $\ddot{x} = -\omega^{2}x$ gives $\omega^{2}=16$, so $\omega = 4$. The period is $T = \dfrac{2\pi}{\omega} = \dfrac{2\pi}{4} = \dfrac{\pi}{2}$ s.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle performs simple harmonic motion of amplitude $5$ m with angular frequency $4$ rad/s. Find its maximum speed.', '["$5$ m/s", "$80$ m/s", "$1.25$ m/s", "$20$ m/s"]'::jsonb, 3, 'In simple harmonic motion the speed is greatest at the centre, where $v_{\max} = a\omega = (5)(4) = 20$ m/s.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a simple pendulum of length $L$ undergoing small oscillations, the period is given by:', '["$T = \\sqrt{2\\pi L/g}$", "$T = 2\\pi\\sqrt{L/g}$", "$T = 2\\pi\\sqrt{g/L}$", "$T = 2\\pi L/g$"]'::jsonb, 1, 'For small oscillations the pendulum performs simple harmonic motion with $\omega^{2} = \dfrac{g}{L}$, so the period is $T = \dfrac{2\pi}{\omega} = 2\pi\sqrt{\dfrac{L}{g}}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'According to Hooke''s law, the tension in an elastic string stretched beyond its natural length is:', '["proportional to the square of the extension produced", "independent of the extension, depending only on the string''s material", "directly proportional to the extension produced", "inversely proportional to the extension produced"]'::jsonb, 2, 'Hooke''s law states that the tension is proportional to the extension: $T = \dfrac{\lambda e}{L}$, where $e$ is the extension, $L$ the natural length and $\lambda$ the modulus of elasticity.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of mass $3$ kg has its velocity changed from $2$ m/s to $8$ m/s along a straight line. Find the impulse it receives.', '["$30$ N s", "$24$ N s", "$18$ N s", "$6$ N s"]'::jsonb, 2, 'Impulse equals the change in momentum: $I = m(v-u) = 3(8-2) = 18$ N s.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of mass $2$ kg moving at $6$ m/s collides with a stationary body of mass $4$ kg, and the two move off together. Find their common velocity.', '["$1.5$ m/s", "$2$ m/s", "$3$ m/s", "$6$ m/s"]'::jsonb, 1, 'Momentum is conserved: $(2)(6) + (4)(0) = (2+4)v$, so $12 = 6v$ and $v = 2$ m/s.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the direct impact of two smooth elastic spheres with coefficient of restitution $e$, Newton''s experimental law states that the relative velocity of separation is:', '["entirely independent of the relative velocity of approach", "$e$ times the relative velocity of approach", "always exactly equal to the relative velocity of approach", "the sum of the two spheres'' initial velocities before impact"]'::jsonb, 1, 'Newton''s experimental law gives $v_2 - v_1 = -e(u_2 - u_1)$: the speed of separation is $e$ times the speed of approach, where the coefficient of restitution $e$ satisfies $0 \leq e \leq 1$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'In a perfectly elastic direct impact between two smooth spheres, the coefficient of restitution has the value:', '["$e = 1$", "$e = 0$", "$e = 0.5$", "$e > 1$"]'::jsonb, 0, 'A perfectly elastic impact conserves kinetic energy, and the speed of separation equals the speed of approach, which requires $e = 1$. A perfectly inelastic impact has $e = 0$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'When two smooth spheres collide obliquely, the components of their velocities along the common tangent at the point of contact are:', '["reversed in direction but unchanged in magnitude", "reduced by a factor equal to the coefficient of restitution", "always reduced to zero immediately after the impact", "unchanged, because the spheres are smooth and exert no tangential impulse"]'::jsonb, 3, 'For smooth spheres the impulse acts only along the line of centres (the common normal). With no tangential impulse, the tangential velocity components are unaffected by the impact; only the normal components change.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the magnitude of $\mathbf{a} = 6\mathbf{i} - 2\mathbf{j} + 3\mathbf{k}$.', '["$5$", "$7$", "$11$", "$\\sqrt{41}$"]'::jsonb, 1, '$|\mathbf{a}| = \sqrt{6^{2}+(-2)^{2}+3^{2}} = \sqrt{36+4+9} = \sqrt{49} = 7$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector makes angles $\alpha$, $\beta$ and $\gamma$ with the positive $x$, $y$ and $z$ axes respectively. Its direction cosines are:', '["$\\sin\\alpha, \\sin\\beta, \\sin\\gamma$", "$\\tan\\alpha, \\tan\\beta, \\tan\\gamma$", "$\\alpha, \\beta, \\gamma$ measured in radians", "$\\cos\\alpha, \\cos\\beta, \\cos\\gamma$"]'::jsonb, 3, 'The direction cosines are precisely the cosines of the angles the vector makes with the coordinate axes: $l=\cos\alpha$, $m=\cos\beta$, $n=\cos\gamma$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 5\mathbf{i} - 3\mathbf{j} + 2\mathbf{k}$ and $\mathbf{b} = -2\mathbf{i} + \mathbf{j} + 4\mathbf{k}$, find $2\mathbf{a} + \mathbf{b}$.', '["$12\\mathbf{i} - 7\\mathbf{j} + 12\\mathbf{k}$", "$8\\mathbf{i} - 5\\mathbf{j} + 8\\mathbf{k}$", "$3\\mathbf{i} - 2\\mathbf{j} + 6\\mathbf{k}$", "$8\\mathbf{i} - 5\\mathbf{j} + 4\\mathbf{k}$"]'::jsonb, 1, '$2\mathbf{a} = 10\mathbf{i} - 6\mathbf{j} + 4\mathbf{k}$. Adding $\mathbf{b}$: $(10-2)\mathbf{i} + (-6+1)\mathbf{j} + (4+4)\mathbf{k} = 8\mathbf{i} - 5\mathbf{j} + 8\mathbf{k}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = 3\mathbf{i} - \mathbf{j} + 2\mathbf{k}$ and $\mathbf{b} = 2\mathbf{i} + 4\mathbf{j} - \mathbf{k}$, find $\mathbf{a} \cdot \mathbf{b}$.', '["$0$", "$12$", "$-4$", "$8$"]'::jsonb, 0, '$\mathbf{a}\cdot\mathbf{b} = (3)(2) + (-1)(4) + (2)(-1) = 6 - 4 - 2 = 0$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a} = \mathbf{i} + 2\mathbf{j}$ and $\mathbf{b} = 3\mathbf{j} + \mathbf{k}$, find $\mathbf{a} \times \mathbf{b}$.', '["$-2\\mathbf{i} + \\mathbf{j} - 3\\mathbf{k}$", "$2\\mathbf{i} + \\mathbf{j} + 3\\mathbf{k}$", "$6\\mathbf{j} + 2\\mathbf{k}$", "$2\\mathbf{i} - \\mathbf{j} + 3\\mathbf{k}$"]'::jsonb, 3, 'The $\mathbf{i}$ component is $(2)(1)-(0)(3) = 2$; the $\mathbf{j}$ component is $-[(1)(1)-(0)(0)] = -1$; the $\mathbf{k}$ component is $(1)(3)-(2)(0) = 3$. So $\mathbf{a}\times\mathbf{b} = 2\mathbf{i} - \mathbf{j} + 3\mathbf{k}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Which statement about the scalar and vector products of two vectors is correct?', '["Both products always yield a scalar quantity", "Both products always yield a vector quantity", "The scalar product yields a vector, while the vector product yields a scalar", "The scalar product yields a scalar, while the vector product yields a vector"]'::jsonb, 3, 'The scalar (dot) product $\mathbf{a}\cdot\mathbf{b} = |\mathbf{a}||\mathbf{b}|\cos\theta$ is a number, whereas the vector (cross) product produces a vector perpendicular to both $\mathbf{a}$ and $\mathbf{b}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t) = \cos t\,\mathbf{i} + \sin t\,\mathbf{j} + t\mathbf{k}$, find $\dfrac{d\mathbf{r}}{dt}$.', '["$-\\sin t\\,\\mathbf{i} + \\cos t\\,\\mathbf{j} + t\\mathbf{k}$", "$-\\sin t\\,\\mathbf{i} + \\cos t\\,\\mathbf{j} + \\mathbf{k}$", "$\\sin t\\,\\mathbf{i} - \\cos t\\,\\mathbf{j} + \\mathbf{k}$", "$-\\cos t\\,\\mathbf{i} - \\sin t\\,\\mathbf{j}$"]'::jsonb, 1, 'Differentiating componentwise: $\dfrac{d}{dt}(\cos t) = -\sin t$, $\dfrac{d}{dt}(\sin t) = \cos t$, and $\dfrac{d}{dt}(t) = 1$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\displaystyle\int_{0}^{1}\left(6t^2\mathbf{i} + 4t\mathbf{j} + 2\mathbf{k}\right)dt$.', '["$6\\mathbf{i} + 4\\mathbf{j} + 2\\mathbf{k}$", "$3\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k}$", "$2\\mathbf{i} + 4\\mathbf{j} + 2\\mathbf{k}$", "$2\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k}$"]'::jsonb, 3, '$\int_0^1 6t^{2}dt = 2$, $\int_0^1 4t\,dt = 2$, and $\int_0^1 2\,dt = 2$, giving $2\mathbf{i} + 2\mathbf{j} + 2\mathbf{k}$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $(3, 4)$ and $(7, 1)$.', '["$7$", "$\\sqrt{7}$", "$25$", "$5$"]'::jsonb, 3, '$d = \sqrt{(7-3)^{2}+(1-4)^{2}} = \sqrt{16+9} = \sqrt{25} = 5$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two lines have gradients $m_1$ and $m_2$. The lines are perpendicular if and only if:', '["$m_1 m_2 = -1$", "$m_1 = m_2$", "$m_1 + m_2 = 0$", "$m_1 m_2 = 1$"]'::jsonb, 0, 'Perpendicular lines satisfy $m_1 m_2 = -1$; equal gradients ($m_1 = m_2$) instead characterise parallel lines.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the perpendicular distance from the origin to the line $5x + 12y - 26 = 0$.', '["$26$", "$\\frac{26}{17}$", "$13$", "$2$"]'::jsonb, 3, '$d = \dfrac{|5(0)+12(0)-26|}{\sqrt{5^{2}+12^{2}}} = \dfrac{26}{\sqrt{169}} = \dfrac{26}{13} = 2$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the radius of the circle $x^2 + y^2 - 6x + 8y = 0$.', '["$25$", "$10$", "$\\sqrt{7}$", "$5$"]'::jsonb, 3, 'Here $2g=-6$ so $g=-3$; $2f=8$ so $f=4$; and $c=0$. The radius is $\sqrt{g^{2}+f^{2}-c} = \sqrt{9+16-0} = \sqrt{25} = 5$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The circle $x^2 + y^2 - 6x + 8y = 0$ passes through which of these points?', '["the point $(6, 8)$", "the point $(3, -4)$", "the origin $(0, 0)$", "the point $(1, 1)$"]'::jsonb, 2, 'Substituting $(0,0)$: $0 + 0 - 0 + 0 = 0$, which satisfies the equation. In general a circle $x^{2}+y^{2}+2gx+2fy+c=0$ passes through the origin exactly when $c=0$, as here.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the parabola $y^2 = 16x$, find the length of the latus rectum.', '["$4$", "$8$", "$32$", "$16$"]'::jsonb, 3, 'For $y^{2}=4ax$ the latus rectum has length $4a$. Here $4a=16$, so the latus rectum is $16$ units long.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A conic section has eccentricity $e$. The conic is an ellipse when:', '["$e > 1$", "$e = 0$ only", "$0 < e < 1$", "$e = 1$"]'::jsonb, 2, 'The eccentricity classifies the conic: $e<1$ gives an ellipse, $e=1$ a parabola, and $e>1$ a hyperbola (a circle is the special case $e=0$).', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the tangent to the curve $y = x^3$ at the point $(1, 1)$.', '["$1$", "$\\frac{1}{3}$", "$-3$", "$3$"]'::jsonb, 3, '$\dfrac{dy}{dx} = 3x^{2}$, so at $x=1$ the gradient is $3(1)^{2} = 3$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves along a line with displacement $s = 2t^3 - 3t^2 + 4t$ metres. Find its velocity at $t = 2$ s.', '["$20$ m/s", "$8$ m/s", "$16$ m/s", "$12$ m/s"]'::jsonb, 2, '$v = \dfrac{ds}{dt} = 6t^{2}-6t+4$. At $t=2$: $v = 24-12+4 = 16$ m/s.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body accelerates uniformly from $10$ m/s to $30$ m/s in $4$ s. Find its acceleration.', '["$10$ m/s$^2$", "$2.5$ m/s$^2$", "$80$ m/s$^2$", "$5$ m/s$^2$"]'::jsonb, 3, 'Using $v = u + at$: $30 = 10 + 4a$, so $4a = 20$ and $a = 5$ m/s$^{2}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A resultant force of $24$ N acts on a body, producing an acceleration of $6$ m/s$^2$. Find the mass of the body.', '["$4$ kg", "$144$ kg", "$18$ kg", "$30$ kg"]'::jsonb, 0, 'From $F = ma$, the mass is $m = \dfrac{F}{a} = \dfrac{24}{6} = 4$ kg.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Newton''s second law of motion states that the rate of change of momentum of a body is:', '["proportional to the applied force and along that force''s direction", "always equal to zero whenever the body is in uniform motion", "inversely proportional to the magnitude of the applied force", "independent of the direction in which the applied force acts"]'::jsonb, 0, 'Newton''s second law states that the rate of change of momentum is proportional to the applied force and occurs along the line of that force, which gives $F = ma$ for constant mass.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A stone is released from rest at a height of $45$ m. Taking $g = 10$ m/s$^2$, find the time it takes to reach the ground.', '["$3$ s", "$4.5$ s", "$9$ s", "$1.5$ s"]'::jsonb, 0, 'Using $h = \dfrac{1}{2}gt^{2}$ with $u=0$: $45 = \dfrac{1}{2}(10)t^{2} = 5t^{2}$, so $t^{2}=9$ and $t=3$ s.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A projectile is fired at $40$ m/s at $30^{\circ}$ to the horizontal. Taking $g = 10$ m/s$^2$, find the greatest height it reaches.', '["$20$ m", "$40$ m", "$80$ m", "$10$ m"]'::jsonb, 0, 'The vertical component of the initial velocity is $u\sin\theta = 40\sin 30^{\circ} = 20$ m/s. The greatest height is $\dfrac{(u\sin\theta)^{2}}{2g} = \dfrac{400}{20} = 20$ m.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two spheres approach each other along a line with relative speed $6$ m/s and separate with relative speed $3$ m/s. Find the coefficient of restitution.', '["$0.5$", "$2$", "$1$", "$0.25$"]'::jsonb, 0, 'The coefficient of restitution is $e = \dfrac{\text{speed of separation}}{\text{speed of approach}} = \dfrac{3}{6} = 0.5$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball of mass $2$ kg moving at $5$ m/s rebounds along the same line at $3$ m/s. Find the magnitude of the impulse it receives.', '["$4$ N s", "$10$ N s", "$6$ N s", "$16$ N s"]'::jsonb, 3, 'Taking the initial direction as positive, the final velocity is $-3$ m/s. The impulse is $m(v-u) = 2(-3-5) = -16$ N s, so its magnitude is $16$ N s.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the magnitude of $\mathbf{a} = \mathbf{i} + 2\mathbf{j} + 2\mathbf{k}$.', '["$\\sqrt{5}$", "$9$", "$3$", "$5$"]'::jsonb, 2, '$|\mathbf{a}| = \sqrt{1^2+2^2+2^2} = \sqrt{9} = 3$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the direction cosines of $\mathbf{a} = \mathbf{i} + 2\mathbf{j} + 2\mathbf{k}$.', '["$(1,\\ 2,\\ 2)$", "$(1/9,\\ 2/9,\\ 2/9)$", "$(3,\\ 6,\\ 6)$", "$(1/3,\\ 2/3,\\ 2/3)$"]'::jsonb, 3, 'Direction cosines are the components divided by the magnitude: $(1/3, 2/3, 2/3)$, since $|\mathbf{a}|=3$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Direction cosines $l$, $m$, $n$ of any vector always satisfy:', '["$lmn=1$", "$l^2+m^2+n^2=1$", "$l+m+n=1$", "$l^2+m^2+n^2=0$"]'::jsonb, 1, 'This identity follows directly from the definition $l=\cos\alpha$, $m=\cos\beta$, $n=\cos\gamma$ applied to a unit vector along $\mathbf{a}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vector from the point $(2,-1,3)$ to the point $(5,3,-1)$.', '["$7\\mathbf{i}+2\\mathbf{j}+2\\mathbf{k}$", "$-3\\mathbf{i}-4\\mathbf{j}+4\\mathbf{k}$", "$3\\mathbf{i}-4\\mathbf{j}-4\\mathbf{k}$", "$3\\mathbf{i}+4\\mathbf{j}-4\\mathbf{k}$"]'::jsonb, 3, 'The vector from one point to another is (final) $-$ (initial): $(5-2)\mathbf{i}+(3-(-1))\mathbf{j}+(-1-3)\mathbf{k} = 3\mathbf{i}+4\mathbf{j}-4\mathbf{k}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector has components $(6, 8, 0)$. Find its magnitude.', '["$48$", "$10$", "$14$", "$2$"]'::jsonb, 1, '$|\mathbf{b}| = \sqrt{6^2+8^2+0^2} = \sqrt{100} = 10$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector making equal angles with all three coordinate axes has direction cosines that are all:', '["Equal to $1/\\sqrt{3}$", "Equal to $1$", "Equal to $\\sqrt{3}$", "Equal to $0$"]'::jsonb, 0, 'If $l=m=n$ and $l^2+m^2+n^2=1$, then $3l^2=1$, so $l=1/\sqrt{3}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The position vector of a point $P(x,y,z)$ relative to the origin is written as:', '["$\\overrightarrow{OP} = x+y+z$", "$\\overrightarrow{OP} = (x+y+z)\\mathbf{i}$", "$\\overrightarrow{OP} = x\\mathbf{i}+y\\mathbf{j}+z\\mathbf{k}$", "$\\overrightarrow{OP} = xyz$"]'::jsonb, 2, 'The position vector collects the point''s coordinates as the components along $\mathbf{i}$, $\mathbf{j}$, $\mathbf{k}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the position vector of the midpoint of the segment joining $(2,3,4)$ and $(6,7,8)$.', '["$8\\mathbf{i}+10\\mathbf{j}+12\\mathbf{k}$", "$2\\mathbf{i}+2\\mathbf{j}+2\\mathbf{k}$", "$4\\mathbf{i}+4\\mathbf{j}+4\\mathbf{k}$", "$4\\mathbf{i}+5\\mathbf{j}+6\\mathbf{k}$"]'::jsonb, 3, 'The midpoint''s position vector is the average of the two position vectors: $\tfrac{1}{2}[(2+6)\mathbf{i}+(3+7)\mathbf{j}+(4+8)\mathbf{k}] = 4\mathbf{i}+5\mathbf{j}+6\mathbf{k}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector of magnitude $10$ has direction cosines $(0.6, 0.8, 0)$. Find its $x$-component.', '["$10.6$", "$60$", "$6$", "$0.6$"]'::jsonb, 2, 'The $x$-component is $|\mathbf{a}|l = 10\times 0.6 = 6$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two direction cosines of a line are $l=1/2$ and $m=1/2$. Find $n$, given $n>0$.', '["$1/2$", "$1$", "$0$", "$1/\\sqrt{2}$"]'::jsonb, 3, '$l^2+m^2+n^2=1 \Rightarrow 1/4+1/4+n^2=1 \Rightarrow n^2=1/2 \Rightarrow n=1/\sqrt{2}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{u}=2\mathbf{i}-3\mathbf{j}$ and $\mathbf{v}=-\mathbf{i}+4\mathbf{j}$, find $2\mathbf{u}-3\mathbf{v}$.', '["$1\\mathbf{i}+1\\mathbf{j}$", "$4\\mathbf{i}-6\\mathbf{j}$", "$-3\\mathbf{i}+12\\mathbf{j}$", "$7\\mathbf{i}-18\\mathbf{j}$"]'::jsonb, 3, '$2\mathbf{u} = 4\mathbf{i}-6\mathbf{j}$ and $3\mathbf{v}=-3\mathbf{i}+12\mathbf{j}$, so $2\mathbf{u}-3\mathbf{v} = (4-(-3))\mathbf{i}+(-6-12)\mathbf{j} = 7\mathbf{i}-18\mathbf{j}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A set of vectors is said to be linearly independent if the only solution to $c_1\mathbf{v}_1+c_2\mathbf{v}_2+\cdots+c_n\mathbf{v}_n=\mathbf{0}$ is:', '["At least one $c_i$ is non-zero", "All the vectors are equal to $\\mathbf{0}$", "$c_1=c_2=\\cdots=c_n=0$", "$c_1=c_2=\\cdots=c_n=1$"]'::jsonb, 2, 'Linear independence means the zero combination is the only way to produce the zero vector -- no non-trivial (not-all-zero) combination of the vectors can equal zero.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two vectors $\mathbf{a}$ and $\mathbf{b}$ in a plane are linearly dependent if and only if they are:', '["Both equal to the zero vector only", "Parallel (one a scalar multiple of the other)", "Perpendicular", "Both unit vectors"]'::jsonb, 1, 'Two nonzero plane vectors are linearly dependent exactly when one is a scalar multiple of the other, i.e. they are parallel.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the value of $k$ for which $\mathbf{a}=2\mathbf{i}+3\mathbf{j}$ and $\mathbf{b}=4\mathbf{i}+k\mathbf{j}$ are parallel.', '["$k=2$", "$k=6$", "$k=3$", "$k=12$"]'::jsonb, 1, 'Parallel vectors have proportional components: $4/2 = k/3$, so $k = 6$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A point $R$ divides the segment from $A(3,1)$ to $B(9,7)$ in the ratio $1{:}1$ (the midpoint). Find the position vector of $R$.', '["$12\\mathbf{i}+8\\mathbf{j}$", "$3\\mathbf{i}+3\\mathbf{j}$", "$9\\mathbf{i}+1\\mathbf{j}$", "$6\\mathbf{i}+4\\mathbf{j}$"]'::jsonb, 3, '$R = A + \tfrac{1}{2}(B-A) = (3,1)+\tfrac{1}{2}(6,6) = (6,4)$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For non-zero vectors $\mathbf{a}$ and $\mathbf{b}$ that are NOT parallel, the equation $x\mathbf{a}+y\mathbf{b}=\mathbf{0}$ forces:', '["$x=0$ and $y=0$", "$x=y$", "$x=-y$", "$x$ and $y$ can be any values"]'::jsonb, 0, 'Since $\mathbf{a}$ and $\mathbf{b}$ are linearly independent (not parallel), the only combination summing to zero is the trivial one.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\mathbf{a}+\mathbf{b}+\mathbf{c}$ given $\mathbf{a}=\mathbf{i}-2\mathbf{j}$, $\mathbf{b}=3\mathbf{i}+5\mathbf{j}$, $\mathbf{c}=-4\mathbf{i}+\mathbf{j}$.', '["$8\\mathbf{i}+4\\mathbf{j}$", "$0\\mathbf{i}+0\\mathbf{j}$", "$4\\mathbf{i}+0\\mathbf{j}$", "$0\\mathbf{i}+4\\mathbf{j}$"]'::jsonb, 3, 'Summing components: $(1+3-4)\mathbf{i}+(-2+5+1)\mathbf{j} = 0\mathbf{i}+4\mathbf{j}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector $\mathbf{a}$ is multiplied by a negative scalar $k$. The resulting vector $k\mathbf{a}$:', '["Becomes the zero vector", "Points in the opposite direction to $\\mathbf{a}$, scaled by $|k|$", "Points in the same direction as $\\mathbf{a}$", "Has the same magnitude as $\\mathbf{a}$ regardless of $k$"]'::jsonb, 1, 'Multiplying by a negative scalar reverses the vector''s direction and scales its magnitude by $|k|$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{p}=4\mathbf{i}-\mathbf{j}$ and $\mathbf{q}=-2\mathbf{i}+3\mathbf{j}$, find $\mathbf{p}-\mathbf{q}$.', '["$2\\mathbf{i}+2\\mathbf{j}$", "$-6\\mathbf{i}+4\\mathbf{j}$", "$6\\mathbf{i}+4\\mathbf{j}$", "$6\\mathbf{i}-4\\mathbf{j}$"]'::jsonb, 3, '$\mathbf{p}-\mathbf{q} = (4-(-2))\mathbf{i}+(-1-3)\mathbf{j} = 6\mathbf{i}-4\mathbf{j}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Three coplanar vectors are always linearly dependent if there are:', '["None at all", "More than two of them in a two-dimensional plane", "Fewer than two of them", "Exactly two of them, and they are not parallel"]'::jsonb, 1, 'In a 2-dimensional plane, any set of more than two vectors must be linearly dependent, since at most two linearly independent vectors can span a plane.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=2\mathbf{i}-\mathbf{j}+3\mathbf{k}$ and $\mathbf{b}=\mathbf{i}+4\mathbf{j}-2\mathbf{k}$, find $\mathbf{a}\cdot\mathbf{b}$.', '["$8$", "$0$", "$-4$", "$-8$"]'::jsonb, 3, '$\mathbf{a}\cdot\mathbf{b} = (2)(1)+(-1)(4)+(3)(-2) = 2-4-6 = -8$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $\mathbf{j} \times \mathbf{i}$.', '["$\\mathbf{k}$", "$\\mathbf{j}$", "$\\mathbf{0}$", "$-\\mathbf{k}$"]'::jsonb, 3, 'By anti-commutativity of the cross product, $\mathbf{j}\times\mathbf{i} = -(\mathbf{i}\times\mathbf{j}) = -\mathbf{k}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{e}=3\mathbf{i}-2\mathbf{j}+\mathbf{k}$ and $\mathbf{f}=\mathbf{i}+\mathbf{j}-\mathbf{k}$, find $\mathbf{e}\times\mathbf{f}$.', '["$-1\\mathbf{i}+4\\mathbf{j}+5\\mathbf{k}$", "$3\\mathbf{i}-2\\mathbf{j}-\\mathbf{k}$", "$\\mathbf{i}+4\\mathbf{j}+5\\mathbf{k}$", "$1\\mathbf{i}-4\\mathbf{j}-5\\mathbf{k}$"]'::jsonb, 2, '$\mathbf{e}\times\mathbf{f} = ((-2)(-1)-(1)(1))\mathbf{i} - ((3)(-1)-(1)(1))\mathbf{j} + ((3)(1)-(-2)(1))\mathbf{k} = \mathbf{i}+4\mathbf{j}+5\mathbf{k}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}\cdot\mathbf{b}=-8$, $|\mathbf{a}|=\sqrt{14}$ and $|\mathbf{b}|=\sqrt{21}$, find $\cos\theta$ between them.', '["$-8$", "$-8/\\sqrt{294}$", "$8/\\sqrt{294}$", "$-8/35$"]'::jsonb, 1, '$\cos\theta = (\mathbf{a}\cdot\mathbf{b})/(|\mathbf{a}||\mathbf{b}|) = -8/(\sqrt{14}\sqrt{21}) = -8/\sqrt{294}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two non-zero vectors satisfy $\mathbf{a}\times\mathbf{b}=\mathbf{0}$. This means the vectors are:', '["Perpendicular", "Equal in magnitude only", "Both unit vectors", "Parallel (or anti-parallel)"]'::jsonb, 3, 'The cross product vanishes exactly when $\sin\theta=0$, i.e. $\theta=0$ or $180^{\circ}$ -- the vectors are parallel or anti-parallel.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the parallelogram whose adjacent sides are $\mathbf{g}=2\mathbf{i}+2\mathbf{j}+\mathbf{k}$ and $\mathbf{h}=\mathbf{i}-2\mathbf{j}+2\mathbf{k}$.', '["$9$", "$3$", "$81$", "$6$"]'::jsonb, 0, '$\mathbf{g}\times\mathbf{h} = 6\mathbf{i}-3\mathbf{j}-6\mathbf{k}$, with magnitude $\sqrt{36+9+36}=\sqrt{81}=9$, which is the area of the parallelogram.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The scalar triple product $\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})$ gives, in magnitude, the:', '["Angle between $\\mathbf{a}$ and $\\mathbf{b}$", "Volume of the parallelepiped formed by the three vectors", "Area of the triangle formed by the three vectors", "Sum of the three vectors"]'::jsonb, 1, 'The scalar triple product''s absolute value equals the volume of the parallelepiped with the three vectors as edges.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate the scalar triple product $\mathbf{i}\cdot(\mathbf{j}\times\mathbf{k})$.', '["$-1$", "$3$", "$1$", "$0$"]'::jsonb, 2, '$\mathbf{j}\times\mathbf{k}=\mathbf{i}$, so $\mathbf{i}\cdot\mathbf{i}=1$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For any two vectors, $\mathbf{a}\times\mathbf{b} = -(\mathbf{b}\times\mathbf{a})$. This property is called:', '["Anti-commutativity", "Associativity", "Distributivity", "Commutativity"]'::jsonb, 0, 'Unlike the dot product, the cross product reverses sign when the order of the vectors is swapped -- it is anti-commutative, not commutative.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=4\mathbf{i}+3\mathbf{k}$ and $\mathbf{b}=5\mathbf{j}$, find $\mathbf{a}\cdot\mathbf{b}$.', '["$20$", "$15$", "$12$", "$0$"]'::jsonb, 3, '$\mathbf{a}\cdot\mathbf{b} = (4)(0)+(0)(5)+(3)(0) = 0$ -- the vectors are perpendicular.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\mathbf{a}\cdot\mathbf{b}=0$ for two non-zero vectors, then the angle between them is:', '["$90^{\\circ}$", "$0^{\\circ}$", "$180^{\\circ}$", "$45^{\\circ}$"]'::jsonb, 0, 'A zero dot product between non-zero vectors means $\cos\theta=0$, so $\theta=90^{\circ}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t) = t^2\mathbf{i}+3t\mathbf{j}+t^3\mathbf{k}$, find $d\mathbf{r}/dt$.', '["$2t\\mathbf{i}+3t\\mathbf{j}+3t^2\\mathbf{k}$", "$2t\\mathbf{i}+3\\mathbf{j}+3t^2\\mathbf{k}$", "$t^2\\mathbf{i}+3\\mathbf{j}+t^3\\mathbf{k}$", "$2\\mathbf{i}+0\\mathbf{j}+6t\\mathbf{k}$"]'::jsonb, 1, 'Differentiate each component separately: $\dfrac{d}{dt}(t^2)=2t$, $\dfrac{d}{dt}(3t)=3$, $\dfrac{d}{dt}(t^3)=3t^2$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t) = \sin t\,\mathbf{i}+\cos t\,\mathbf{j}$, find $d\mathbf{r}/dt$.', '["$\\cos t\\,\\mathbf{i}-\\sin t\\,\\mathbf{j}$", "$-\\cos t\\,\\mathbf{i}+\\sin t\\,\\mathbf{j}$", "$\\sin t\\,\\mathbf{i}+\\cos t\\,\\mathbf{j}$", "$-\\sin t\\,\\mathbf{i}-\\cos t\\,\\mathbf{j}$"]'::jsonb, 0, '$\dfrac{d}{dt}(\sin t)=\cos t$ and $\dfrac{d}{dt}(\cos t)=-\sin t$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\int \mathbf{v}(t)\,dt$ given $\mathbf{v}(t)=2t\mathbf{i}+t^2\mathbf{j}$ (ignore the constant of integration).', '["$t^2\\mathbf{i}+\\tfrac{1}{3}t^3\\mathbf{j}$", "$2\\mathbf{i}+2t\\mathbf{j}$", "$t^2\\mathbf{i}+t^3\\mathbf{j}$", "$\\tfrac{1}{2}t^2\\mathbf{i}+\\tfrac{1}{3}t^3\\mathbf{j}$"]'::jsonb, 0, '$\int 2t\,dt = t^2$ and $\int t^2\,dt = \tfrac{1}{3}t^3$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a particle with position vector $\mathbf{r}(t)$, the vector $d\mathbf{r}/dt$ represents its:', '["Velocity", "Acceleration", "Displacement", "Mass"]'::jsonb, 0, 'Velocity is defined as the rate of change of position with respect to time, $\mathbf{v}=d\mathbf{r}/dt$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a particle with velocity vector $\mathbf{v}(t)$, the vector $d\mathbf{v}/dt$ represents its:', '["Velocity", "Position", "Momentum divided by time squared", "Acceleration"]'::jsonb, 3, 'Acceleration is the rate of change of velocity, $\mathbf{a}=d\mathbf{v}/dt = d^2\mathbf{r}/dt^2$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle has position vector $\mathbf{r}(t)=3t^2\mathbf{i}+2t\mathbf{j}+5\mathbf{k}$. Find its acceleration vector.', '["$6\\mathbf{i}+2\\mathbf{j}$", "$6\\mathbf{i}$", "$6t\\mathbf{i}+2\\mathbf{j}$", "$0$"]'::jsonb, 1, '$\mathbf{v} = 6t\mathbf{i}+2\mathbf{j}$, then $\mathbf{a} = d\mathbf{v}/dt = 6\mathbf{i}$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The product rule for differentiating $\mathbf{a}(t)\cdot\mathbf{b}(t)$ with respect to $t$ gives:', '["$\\dfrac{d\\mathbf{a}}{dt}\\cdot\\dfrac{d\\mathbf{b}}{dt}$, the dot product of the two derivatives", "$\\dfrac{d\\mathbf{a}}{dt}\\cdot\\mathbf{b} + \\mathbf{a}\\cdot\\dfrac{d\\mathbf{b}}{dt}$", "$\\dfrac{d\\mathbf{a}}{dt}\\times\\dfrac{d\\mathbf{b}}{dt}$, the cross product of the two derivatives", "$\\mathbf{a}\\cdot\\mathbf{b}$, unchanged from the original product"]'::jsonb, 1, 'The product rule extends naturally to the dot product of two vector-valued functions of $t$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance between the points $(3,6)$ and $(7,9)$.', '["$25$", "$3$", "$5$", "$7$"]'::jsonb, 2, '$d = \sqrt{(7-3)^2+(9-6)^2} = \sqrt{16+9} = \sqrt{25} = 5$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the line joining $(3,6)$ and $(7,9)$.', '["$15$", "$3/4$", "$4/3$", "$-3/4$"]'::jsonb, 1, '$m = (y_2-y_1)/(x_2-x_1) = (9-6)/(7-3) = 3/4$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through $(0,2)$ with gradient $3$.', '["$y=3x-2$", "$y=x+2$", "$y=3x+2$", "$y=2x+3$"]'::jsonb, 2, 'Using $y=mx+c$ with $m=3$ and the $y$-intercept $c=2$: $y=3x+2$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two lines with gradients $m_1=2$ and $m_2=-1/2$ are:', '["Coincident", "Neither parallel nor perpendicular", "Perpendicular", "Parallel"]'::jsonb, 2, '$m_1m_2 = 2\times(-1/2) = -1$, so the lines are perpendicular.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of a line perpendicular to $y=4x-1$.', '["$-4$", "$-1/4$", "$4$", "$1/4$"]'::jsonb, 1, 'A perpendicular gradient satisfies $m_1m_2=-1$, so $m_2 = -1/4$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the midpoint of the segment joining $(2,3)$ and $(8,7)$.', '["$(6,4)$", "$(5,5)$", "$(10,10)$", "$(3,2)$"]'::jsonb, 1, 'Midpoint $= \left(\dfrac{2+8}{2}, \dfrac{3+7}{2}\right) = (5,5)$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line through $(1,2)$ and $(3,8)$.', '["$y=3x+1$", "$y=x+1$", "$y=6x-4$", "$y=3x-1$"]'::jsonb, 3, '$m = (8-2)/(3-1) = 3$. Using point $(1,2)$: $y-2=3(x-1)$, so $y=3x-1$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the area of the triangle with vertices $(0,0)$, $(6,0)$ and $(0,4)$.', '["$24$", "$10$", "$6$", "$12$"]'::jsonb, 3, 'This is a right triangle with legs $6$ and $4$ along the axes, so its area is $\tfrac{1}{2}(6)(4) = 12$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the perpendicular distance from $(4,0)$ to the line $3x - 4y - 5 = 0$.', '["$5/7$", "$7$", "$5$", "$7/5$"]'::jsonb, 3, '$d = |3(4)-4(0)-5|/\sqrt{3^2+4^2} = |7|/5 = 7/5$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The equation $2x + 3y = 6$ can be rewritten in gradient-intercept form $y=mx+c$ as:', '["$y = 2x + 3$", "$y = -\\tfrac{2}{3}x + 2$", "$y = \\tfrac{2}{3}x + 2$", "$y = -\\tfrac{3}{2}x + 2$"]'::jsonb, 1, '$3y = -2x+6$, so $y = -\tfrac{2}{3}x + 2$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Three points are collinear if the gradient between the first and second point:', '["Is always zero", "Is undefined", "Is the negative reciprocal of the other gradient", "Equals the gradient between the second and third point"]'::jsonb, 3, 'Collinear points all lie on one straight line, so the gradient computed from any two of them must agree.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the $x$-intercept of the line $y = 2x - 8$.', '["$(0,-8)$", "$(-4,0)$", "$(8,0)$", "$(4,0)$"]'::jsonb, 3, 'Set $y=0$: $0=2x-8 \Rightarrow x=4$, so the $x$-intercept is $(4,0)$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The equation $x^2+y^2=25$ represents a circle with centre and radius:', '["Centre $(5,5)$, radius $5$", "Centre $(0,0)$, radius $\\sqrt{5}$", "Centre $(0,0)$, radius $5$", "Centre $(0,0)$, radius $25$"]'::jsonb, 2, 'Comparing with $x^2+y^2=r^2$ gives $r^2=25$, so $r=5$, centred at the origin.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of a circle with centre $(2,-3)$ and radius $4$.', '["$(x+2)^2+(y-3)^2=16$", "$(x-2)^2+(y+3)^2=4$", "$(x-2)^2+(y-3)^2=16$", "$(x-2)^2+(y+3)^2=16$"]'::jsonb, 3, 'The standard form is $(x-a)^2+(y-b)^2=r^2$ with $(a,b)=(2,-3)$ and $r=4$, giving $(x-2)^2+(y+3)^2=16$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the centre of the circle $x^2+y^2+6x+8y-11=0$.', '["$(3,4)$", "$(6,8)$", "$(-6,-8)$", "$(-3,-4)$"]'::jsonb, 3, 'Completing the square: centre $= (-g,-f)$ where $2g=6$, $2f=8$, so $g=3$, $f=4$, giving centre $(-3,-4)$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the general circle equation $x^2+y^2+2gx+2fy+c=0$, the radius is given by:', '["$\\sqrt{g^2+f^2-c}$", "$\\sqrt{g^2+f^2+c}$", "$g^2+f^2-c$", "$\\sqrt{c-g^2-f^2}$"]'::jsonb, 0, 'Completing the square on the general form gives radius $r=\sqrt{g^2+f^2-c}$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A circle has centre $(1,2)$ and passes through $(4,6)$. Find its radius.', '["$25$", "$7$", "$3$", "$5$"]'::jsonb, 3, '$r = \sqrt{(4-1)^2+(6-2)^2} = \sqrt{9+16} = \sqrt{25} = 5$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A line is tangent to a circle when the perpendicular distance from the circle''s centre to the line equals:', '["The diameter of the circle", "The radius of the circle", "Twice the radius of the circle", "Zero"]'::jsonb, 1, 'A tangent touches the circle at exactly one point, which happens precisely when the centre-to-line distance equals the radius.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A circle has equation $x^2+y^2=16$. Determine whether the point $(3,4)$ lies inside, on, or outside the circle.', '["On the circle, since $3^2+4^2=16$", "Inside, since $3^2+4^2 < 16$", "At the centre of the circle", "Outside, since $3^2+4^2 = 25 > 16$"]'::jsonb, 3, '$3^2+4^2 = 9+16 = 25$, which is greater than $16=r^2$, so the point lies outside the circle.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The circle with the segment from $(-3,0)$ to $(5,0)$ as a diameter has its centre at:', '["$(-1,0)$", "$(4,0)$", "$(1,0)$", "$(2,0)$"]'::jsonb, 2, 'The centre of a circle drawn on a diameter is the midpoint of that diameter: $\left(\dfrac{-3+5}{2},0\right) = (1,0)$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'From an external point, the two tangent lines drawn to a circle always have:', '["Different lengths", "A length equal to the circle''s radius", "A length equal to the circle''s diameter", "Equal length"]'::jsonb, 3, 'By the symmetry of the circle about the line joining the external point to the centre, the two tangent segments from that point are always equal in length.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the parabola $y^2=4ax$, the coordinates of the focus are:', '["$(0,a)$", "$(-a,0)$", "$(4a,0)$", "$(a,0)$"]'::jsonb, 3, 'The standard parabola $y^2=4ax$ opens along the positive $x$-axis with focus at $(a,0)$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the value of $a$ for the parabola $y^2=12x$.', '["$6$", "$4$", "$3$", "$12$"]'::jsonb, 2, 'Comparing $y^2=12x$ with $y^2=4ax$ gives $4a=12$, so $a=3$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the parabola $y^2=4ax$, the equation of the directrix is:', '["$x=-a$", "$x=a$", "$y=-a$", "$x=0$"]'::jsonb, 0, 'The directrix of $y^2=4ax$ is the vertical line $x=-a$, on the opposite side of the vertex from the focus.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$ with $a>b$, the eccentricity $e$ is defined by:', '["$e=a/b$", "$e=a+b$", "$b^2=a^2(1-e^2)$", "$a^2=b^2(1-e^2)$"]'::jsonb, 2, 'The standard relation for an ellipse is $b^2=a^2(1-e^2)$, with $0<e<1$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{25}+\dfrac{y^2}{9}=1$, find the eccentricity.', '["$16/25$", "$4/5$", "$3/5$", "$9/25$"]'::jsonb, 1, '$a^2=25$, $b^2=9$, so $e = \sqrt{1-b^2/a^2} = \sqrt{1-9/25} = \sqrt{16/25} = 4/5$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{25}+\dfrac{y^2}{9}=1$, find the coordinates of the foci.', '["$(0, \\pm 4)$", "$(\\pm 4, 0)$", "$(\\pm 5, 0)$", "$(\\pm 3, 0)$"]'::jsonb, 1, 'The foci lie at $(\pm ae, 0) = (\pm 5 \times 4/5, 0) = (\pm 4, 0)$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a hyperbola $\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$, the eccentricity satisfies:', '["$b^2=a^2(e^2-1)$", "$b^2=a^2(1-e^2)$", "$e<1$ always", "$a^2=b^2(e^2-1)$"]'::jsonb, 0, 'For a hyperbola, $b^2=a^2(e^2-1)$, with eccentricity $e>1$ (unlike the ellipse, where $e<1$).', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the hyperbola $\dfrac{x^2}{16}-\dfrac{y^2}{9}=1$, find the eccentricity.', '["$3/4$", "$7/4$", "$5/4$", "$4/5$"]'::jsonb, 2, '$a^2=16$, $b^2=9$, so $e=\sqrt{1+b^2/a^2}=\sqrt{1+9/16}=\sqrt{25/16}=5/4$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The asymptotes of the hyperbola $\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$ are the lines:', '["$y=\\pm ab\\,x$", "$x=\\pm a$", "$y=\\pm(b/a)x$", "$y=\\pm(a/b)x$"]'::jsonb, 2, 'As $x\to\pm\infty$, the hyperbola approaches the straight lines $y=\pm(b/a)x$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The eccentricity of a circle, viewed as a special case of an ellipse, is:', '["$0$", "$1$", "Undefined", "$\\infty$"]'::jsonb, 0, 'A circle is an ellipse with $a=b$, so $e=\sqrt{1-b^2/a^2}=\sqrt{1-1}=0$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{25}+\dfrac{y^2}{9}=1$, find the length of the latus rectum, $2b^2/a$.', '["$9/5$", "$36/5$", "$5$", "$18/5$"]'::jsonb, 3, '$2b^2/a = 2(9)/5 = 18/5$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A conic section is classified as a parabola when its eccentricity equals:', '["A value less than $1$", "A value greater than $1$", "$1$", "$0$"]'::jsonb, 2, '$e=0$ gives a circle, $0<e<1$ an ellipse, $e=1$ a parabola, and $e>1$ a hyperbola.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The normal to a curve at a point is the line through that point that is:', '["Always horizontal", "Always vertical", "Perpendicular to the tangent at that point", "Parallel to the tangent at that point"]'::jsonb, 2, 'The normal is, by definition, perpendicular to the tangent line at the point of contact.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the tangent to $y=x^2$ at the point $(2,4)$.', '["$2$", "$16$", "$8$", "$4$"]'::jsonb, 3, '$dy/dx = 2x$, so at $x=2$, the gradient of the tangent is $4$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the curve $y=x^2$ at $(2,4)$, find the equation of the tangent line.', '["$y=4x-8$", "$y=4x-4$", "$y=4x+4$", "$y=2x$"]'::jsonb, 1, 'Gradient is $4$ at $(2,4)$: $y-4=4(x-2) \Rightarrow y=4x-4$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the curve $y=x^2$ at $(2,4)$, find the gradient of the normal.', '["$-1/4$", "$4$", "$1/4$", "$-4$"]'::jsonb, 0, 'The normal''s gradient is the negative reciprocal of the tangent''s gradient: $-1/4$, since $4\times(-1/4)=-1$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the tangent to the circle $x^2+y^2=25$ at the point $(3,4)$, using implicit differentiation.', '["$-3/4$", "$3/4$", "$4/3$", "$-4/3$"]'::jsonb, 0, 'Differentiating implicitly: $2x+2y\,dy/dx=0 \Rightarrow dy/dx=-x/y = -3/4$ at $(3,4)$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The normal to a circle at any point on its circumference always passes through the:', '["Point diametrically opposite", "Origin, regardless of the circle''s centre", "Point where the tangent meets the $x$-axis", "Centre of the circle"]'::jsonb, 3, 'Since the radius is perpendicular to the tangent at the point of contact, the normal line at any point on a circle always passes through the centre.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $dy/dx$ for $y = x^3 - 3x$ at $x=1$, the gradient of the tangent there.', '["$1$", "$0$", "$3$", "$-3$"]'::jsonb, 1, '$dy/dx = 3x^2-3$; at $x=1$: $3(1)-3=0$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The tangent to a curve at a point where $dy/dx=0$ is:', '["Vertical", "At $45^{\\circ}$ to the $x$-axis", "Undefined", "Horizontal"]'::jsonb, 3, 'A zero gradient means the tangent line is horizontal at that point.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle starts from rest and accelerates uniformly at $6\ \text{m/s}^2$ for $5\ \text{s}$. Find its final velocity.', '["$30\\ \\text{m/s}$", "$11\\ \\text{m/s}$", "$1.2\\ \\text{m/s}$", "$150\\ \\text{m/s}$"]'::jsonb, 0, '$v=u+at = 0+(6)(5) = 30\ \text{m/s}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle has initial velocity $4\ \text{m/s}$ and accelerates at $2\ \text{m/s}^2$. Find the distance covered in $3\ \text{s}$.', '["$18\\ \\text{m}$", "$21\\ \\text{m}$", "$12\\ \\text{m}$", "$9\\ \\text{m}$"]'::jsonb, 1, '$s = ut+\tfrac{1}{2}at^2 = 4(3)+\tfrac{1}{2}(2)(9) = 12+9=21\ \text{m}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle with initial velocity $6\ \text{m/s}$ accelerates at $4\ \text{m/s}^2$ over $20\ \text{m}$. Find its final velocity.', '["$26\\ \\text{m/s}$", "$196\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$14\\ \\text{m/s}$"]'::jsonb, 3, '$v^2 = u^2+2as = 36+160 = 196$, so $v = \sqrt{196}=14\ \text{m/s}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves so that $s = 2t^3-9t^2+12t$. Find its velocity as a function of $t$.', '["$v = 6t^2-18t+12$", "$v = 2t^2-9t+12$", "$v = 6t^2-18t$", "$v = t^3-9t^2+12t$"]'::jsonb, 0, '$v = ds/dt = 6t^2-18t+12$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the particle with $s=2t^3-9t^2+12t$, find its acceleration as a function of $t$.', '["$a=2t-9$", "$a=12t-18$", "$a=6t^2-18t$", "$a=6t-18$"]'::jsonb, 1, '$a = dv/dt = 12t-18$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the particle with $v=6t^2-18t+12$, find the times (in seconds) at which the particle is momentarily at rest.', '["$t=0$ and $t=3$", "$t=2$ and $t=3$", "$t=1$ only", "$t=1$ and $t=2$"]'::jsonb, 3, 'Setting $v=0$: $6t^2-18t+12=0 \Rightarrow t^2-3t+2=0 \Rightarrow (t-1)(t-2)=0$, so $t=1$ or $t=2$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle''s displacement is given by $s=5t-t^2$ (in metres, $t$ in seconds). Find the maximum displacement reached.', '["$5\\ \\text{m}$", "$2.5\\ \\text{m}$", "$25\\ \\text{m}$", "$6.25\\ \\text{m}$"]'::jsonb, 3, 'Maximum occurs when $ds/dt=5-2t=0 \Rightarrow t=2.5$. Then $s=5(2.5)-(2.5)^2=12.5-6.25=6.25\ \text{m}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A car decelerates from $30\ \text{m/s}$ to rest at a constant rate of $5\ \text{m/s}^2$. Find the time taken to stop.', '["$25\\ \\text{s}$", "$35\\ \\text{s}$", "$6\\ \\text{s}$", "$150\\ \\text{s}$"]'::jsonb, 2, '$t = (v-u)/a = (0-30)/(-5) = 6\ \text{s}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the same car (decelerating from $30\ \text{m/s}$ at $5\ \text{m/s}^2$), find the distance travelled before stopping.', '["$6\\ \\text{m}$", "$90\\ \\text{m}$", "$180\\ \\text{m}$", "$30\\ \\text{m}$"]'::jsonb, 1, '$v^2=u^2-2as \Rightarrow 0=900-10s \Rightarrow s=90\ \text{m}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle has position vector $\mathbf{r}(t)=3t\mathbf{i}+(4t-t^2)\mathbf{j}$. Find its velocity vector.', '["$3\\mathbf{i}-2t\\mathbf{j}$", "$3\\mathbf{i}+(4-2t)\\mathbf{j}$", "$3\\mathbf{i}+4\\mathbf{j}$", "$3t\\mathbf{i}+(4-2t)\\mathbf{j}$"]'::jsonb, 1, 'Differentiate each component: $d(3t)/dt=3$, $d(4t-t^2)/dt=4-2t$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the particle above, find its speed at $t=1$.', '["$5$", "$7$", "$3$", "$\\sqrt{13}$"]'::jsonb, 3, 'At $t=1$: $\mathbf{v}=3\mathbf{i}+2\mathbf{j}$, so speed $=\sqrt{3^2+2^2}=\sqrt{13}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the particle with $\mathbf{r}(t)=3t\mathbf{i}+(4t-t^2)\mathbf{j}$, find its acceleration vector.', '["$0$", "$2\\mathbf{j}$", "$-2\\mathbf{j}$", "$3\\mathbf{i}$"]'::jsonb, 2, 'Differentiating $\mathbf{v}=3\mathbf{i}+(4-2t)\mathbf{j}$ gives $\mathbf{a}=-2\mathbf{j}$, constant.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a particle moving in a plane with position vector $\mathbf{r}(t)=x(t)\mathbf{i}+y(t)\mathbf{j}$, the speed of the particle is given by:', '["$dx/dt-dy/dt$", "$\\sqrt{(dx/dt)^2+(dy/dt)^2}$", "$dx/dt+dy/dt$", "$(dx/dt)(dy/dt)$"]'::jsonb, 1, 'Speed is the magnitude of the velocity vector, $|\mathbf{v}|=\sqrt{\dot{x}^2+\dot{y}^2}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moves on the circle $\mathbf{r}(t)=5\cos t\,\mathbf{i}+5\sin t\,\mathbf{j}$. Find its speed.', '["$0$", "$5$", "$25$", "$1$"]'::jsonb, 1, '$\mathbf{v}=-5\sin t\,\mathbf{i}+5\cos t\,\mathbf{j}$, so speed $=\sqrt{25\sin^2t+25\cos^2t}=5$, constant.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moving with constant speed on a circular path still has a non-zero acceleration because its:', '["Speed is continuously changing", "Mass is continuously changing", "Radius is continuously changing", "Direction of motion is continuously changing"]'::jsonb, 3, 'Acceleration is the rate of change of the velocity vector; even at constant speed, the direction of $\mathbf{v}$ changes continuously on a circular path, producing centripetal acceleration.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'In projectile motion, resolving the initial velocity $u$ at angle $\theta$ into components gives the horizontal and vertical parts as:', '["$u$ and $u\\theta$", "$u\\cos\\theta$ and $u\\sin\\theta$", "$u\\sin\\theta$ and $u\\cos\\theta$", "$u\\tan\\theta$ and $u$"]'::jsonb, 1, 'The horizontal component is $u\cos\theta$ and the vertical component is $u\sin\theta$, resolving along the two perpendicular axes.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the force needed to give a mass of $8\ \text{kg}$ an acceleration of $3\ \text{m/s}^2$.', '["$24\\ \\text{N}$", "$11\\ \\text{N}$", "$5\\ \\text{N}$", "$2.67\\ \\text{N}$"]'::jsonb, 0, '$F=ma=8\times3=24\ \text{N}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A resultant force of $15\ \text{N}$ acts on a body of mass $5\ \text{kg}$. Find the acceleration produced.', '["$0.33\\ \\text{m/s}^2$", "$3\\ \\text{m/s}^2$", "$75\\ \\text{m/s}^2$", "$10\\ \\text{m/s}^2$"]'::jsonb, 1, '$a=F/m=15/5=3\ \text{m/s}^2$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the momentum of a body of mass $4\ \text{kg}$ moving at $7\ \text{m/s}$.', '["$28\\ \\text{kg·m/s}$", "$11\\ \\text{kg·m/s}$", "$1.75\\ \\text{kg·m/s}$", "$14\\ \\text{kg·m/s}$"]'::jsonb, 0, '$p=mv=4\times7=28\ \text{kg·m/s}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Newton''s second law of motion, $F=ma$, is more generally stated in terms of momentum as:', '["$F = pt$", "$F = dp/dt$, the rate of change of momentum", "$F = p/t$", "$F$ is always constant"]'::jsonb, 1, 'In its general form, Newton''s second law states that force equals the rate of change of momentum, $F=dp/dt$, which reduces to $F=ma$ for constant mass.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of mass $3\ \text{kg}$ moving at $4\ \text{m/s}$ collides and sticks to a stationary $1\ \text{kg}$ body. Find the common velocity after impact.', '["$3\\ \\text{m/s}$", "$4\\ \\text{m/s}$", "$12\\ \\text{m/s}$", "$1\\ \\text{m/s}$"]'::jsonb, 0, 'By momentum conservation: $(3)(4)+0=(3+1)v \Rightarrow v=12/4=3\ \text{m/s}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A resultant force of $20\ \text{N}$ acts on a body for $3\ \text{s}$. Find the impulse delivered.', '["$60\\ \\text{N·s}$", "$6.67\\ \\text{N·s}$", "$23\\ \\text{N·s}$", "$17\\ \\text{N·s}$"]'::jsonb, 0, 'Impulse $=Ft=20\times3=60\ \text{N·s}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Newton''s third law states that for every action there is a reaction that is:', '["Equal in magnitude and in the same direction", "Half the magnitude and opposite in direction", "Always zero", "Equal in magnitude and opposite in direction"]'::jsonb, 3, 'Every force is met by an equal, oppositely directed force acting on the other body in the interaction.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of mass $6\ \text{kg}$ is acted on by two forces: $10\ \text{N}$ east and $10\ \text{N}$ west. Find its acceleration.', '["$3.33\\ \\text{m/s}^2$ east", "$3.33\\ \\text{m/s}^2$ west", "$1.67\\ \\text{m/s}^2$", "$0\\ \\text{m/s}^2$, since the forces cancel"]'::jsonb, 3, 'The two forces are equal and opposite, so the resultant force is zero, giving zero acceleration.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of weight $W$ resting on a horizontal table experiences a normal reaction $R$ from the table. In equilibrium, $R$ equals:', '["$0$", "$W$", "$2W$", "$W/2$"]'::jsonb, 1, 'For the body to remain in vertical equilibrium, the upward normal reaction must exactly balance the downward weight.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The weight of a body is the force with which:', '["The Earth attracts the body, equal to $mg$", "The body attracts the Earth only", "The body resists any change in motion", "Air resistance acts on the body"]'::jsonb, 0, 'Weight is the gravitational force on the body, $W=mg$, distinct from its mass $m$, which is an intrinsic property.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the weight of a $10\ \text{kg}$ mass, taking $g=9.8\ \text{m/s}^2$.', '["$9.8\\ \\text{N}$", "$1.02\\ \\text{N}$", "$98\\ \\text{N}$", "$10\\ \\text{N}$"]'::jsonb, 2, '$W=mg=10\times9.8=98\ \text{N}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball is thrown vertically upward at $25\ \text{m/s}$. Taking $g=10\ \text{m/s}^2$, find the maximum height reached.', '["$31.25\\ \\text{m}$", "$62.5\\ \\text{m}$", "$2.5\\ \\text{m}$", "$25\\ \\text{m}$"]'::jsonb, 0, '$h=u^2/2g=625/20=31.25\ \text{m}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A projectile is launched vertically at $20\ \text{m/s}$. Taking $g=10\ \text{m/s}^2$, find its total time of flight until it returns to its starting height.', '["$4\\ \\text{s}$", "$2\\ \\text{s}$", "$40\\ \\text{s}$", "$0.5\\ \\text{s}$"]'::jsonb, 0, 'Total time of flight $=2u/g=2(20)/10=4\ \text{s}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A projectile is launched at $30\ \text{m/s}$ at $30^{\circ}$ to the horizontal. Taking $g=10\ \text{m/s}^2$, find its horizontal range, $R=u^2\sin(2\theta)/g$, to the nearest metre.', '["$90\\ \\text{m}$", "$45\\ \\text{m}$", "$30\\ \\text{m}$", "$78\\ \\text{m}$"]'::jsonb, 3, '$R = (900)\sin(60^{\circ})/10 = 90(0.866) \approx 78\ \text{m}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A stone is dropped from rest and falls for $4\ \text{s}$. Taking $g=10\ \text{m/s}^2$, find the distance it falls.', '["$80\\ \\text{m}$", "$40\\ \\text{m}$", "$20\\ \\text{m}$", "$160\\ \\text{m}$"]'::jsonb, 0, '$s=\tfrac{1}{2}gt^2=\tfrac{1}{2}(10)(16)=80\ \text{m}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the same stone (falling for $4\ \text{s}$ under $g=10\ \text{m/s}^2$), find its speed on impact.', '["$10\\ \\text{m/s}$", "$40\\ \\text{m/s}$", "$80\\ \\text{m/s}$", "$4\\ \\text{m/s}$"]'::jsonb, 1, '$v=gt=10\times4=40\ \text{m/s}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'In projectile motion (ignoring air resistance), the vertical component of velocity at the highest point of the path is:', '["Equal to the horizontal component", "Maximum", "Equal to $u$", "Zero"]'::jsonb, 3, 'At the peak of the trajectory the projectile momentarily stops rising, so its vertical velocity component is exactly zero (though the horizontal component is unchanged).', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball thrown vertically upward returns to its starting point with a speed that is:', '["Less than its initial launch speed", "Zero", "Equal to its initial launch speed", "Greater than its initial launch speed"]'::jsonb, 2, 'By energy conservation (ignoring air resistance), the ball returns to the same height with the same speed it was launched at, just directed downward instead of upward.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a fixed launch speed $u=20\ \text{m/s}$ and $g=10\ \text{m/s}^2$, find the maximum possible horizontal range (achieved at $\theta=45^{\circ}$).', '["$40\\ \\text{m}$", "$20\\ \\text{m}$", "$80\\ \\text{m}$", "$400\\ \\text{m}$"]'::jsonb, 0, 'Maximum range $=u^2/g=400/10=40\ \text{m}$, occurring when $\sin(2\theta)=1$, i.e. $\theta=45^{\circ}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle executes SHM with angular frequency $\omega=4\ \text{rad/s}$. Find its period.', '["$\\pi/2\\ \\text{s}$", "$4\\pi\\ \\text{s}$", "$8\\pi\\ \\text{s}$", "$2\\pi\\ \\text{s}$"]'::jsonb, 0, '$T=2\pi/\omega=2\pi/4=\pi/2\ \text{s}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the same particle ($\omega=4\ \text{rad/s}$), find its frequency in Hz, to 2 decimal places.', '["$1.57\\ \\text{Hz}$", "$0.25\\ \\text{Hz}$", "$0.64\\ \\text{Hz}$", "$4.00\\ \\text{Hz}$"]'::jsonb, 2, '$f=\omega/2\pi=4/(2\pi)\approx0.64\ \text{Hz}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A simple pendulum has length $4\ \text{m}$. Taking $g=10\ \text{m/s}^2$, find its period, to 2 decimal places.', '["$1.99\\ \\text{s}$", "$6.28\\ \\text{s}$", "$0.4\\ \\text{s}$", "$3.97\\ \\text{s}$"]'::jsonb, 3, '$T=2\pi\sqrt{\ell/g}=2\pi\sqrt{4/10}\approx3.97\ \text{s}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A simple pendulum''s period is quadrupled when its length is:', '["Multiplied by $8$", "Multiplied by $16$", "Multiplied by $4$", "Multiplied by $2$"]'::jsonb, 1, 'Since $T\propto\sqrt{\ell}$, quadrupling $T$ requires $\ell$ to increase by a factor of $4^2=16$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'An elastic string of natural length $2\ \text{m}$ is stretched by $0.04\ \text{m}$ under a tension of $50\ \text{N}$. Find its modulus of elasticity, using $T = \lambda x/\ell_0$.', '["$100\\ \\text{N}$", "$1250\\ \\text{N}$", "$2500\\ \\text{N}$", "$25\\ \\text{N}$"]'::jsonb, 2, '$T=\lambda x/\ell_0 \Rightarrow 50 = \lambda(0.04)/2 \Rightarrow \lambda = 50\times2/0.04 = 2500\ \text{N}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Hooke''s law for an elastic string states that the tension is proportional to the:', '["Natural length alone, regardless of stretch", "Extension from its natural length", "Total stretched length", "Square of the extension"]'::jsonb, 1, '$T=\lambda x/\ell_0$, so tension is directly proportional to the extension $x$ beyond the natural length $\ell_0$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle in SHM has amplitude $5\ \text{m}$ and angular frequency $3\ \text{rad/s}$. Find its maximum speed.', '["$45\\ \\text{m/s}$", "$15\\ \\text{m/s}$", "$1.67\\ \\text{m/s}$", "$8\\ \\text{m/s}$"]'::jsonb, 1, '$v_{max}=A\omega=5\times3=15\ \text{m/s}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the same SHM particle ($A=5\ \text{m}$, $\omega=3\ \text{rad/s}$), find its maximum acceleration.', '["$15\\ \\text{m/s}^2$", "$5\\ \\text{m/s}^2$", "$9\\ \\text{m/s}^2$", "$45\\ \\text{m/s}^2$"]'::jsonb, 3, '$a_{max}=A\omega^2=5\times9=45\ \text{m/s}^2$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'In SHM, the restoring force is always directed:', '["Along the same direction as the instantaneous velocity", "Perpendicular to the displacement at every instant", "Toward the equilibrium position, opposite to the displacement", "Away from the equilibrium position, in the same sense as the displacement"]'::jsonb, 2, 'The defining feature of SHM is a restoring force (and hence acceleration) that always points back toward equilibrium, opposing the displacement.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Newton''s experimental law of restitution relates the relative speed of separation to the relative speed of approach through the coefficient of restitution $e$, where:', '["$e$ is always equal to $1$", "$e$ is always greater than $1$", "$e = \\dfrac{\\text{speed of separation}}{\\text{speed of approach}}$", "$e = \\text{speed of approach} \\times \\text{speed of separation}$"]'::jsonb, 2, 'The coefficient of restitution is defined as the ratio of the relative speed of separation to the relative speed of approach, with $0\le e\le1$ for real collisions.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A perfectly elastic collision is one in which the coefficient of restitution equals:', '["$0.5$", "A value greater than $1$", "$1$", "$0$"]'::jsonb, 2, '$e=1$ characterises a perfectly elastic collision, in which kinetic energy is also conserved.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A perfectly inelastic collision, in which the two bodies stick together after impact, has a coefficient of restitution equal to:', '["$-1$", "$0.5$ always", "$0$", "$1$"]'::jsonb, 2, 'When the bodies move off with the same velocity (stick together), there is no separation speed, so $e=0$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two spheres approach each other; sphere A moves at $6\ \text{m/s}$ toward a stationary sphere B. If $e=0.6$, find the speed of separation after impact.', '["$6\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$0.6\\ \\text{m/s}$", "$3.6\\ \\text{m/s}$"]'::jsonb, 3, 'Speed of separation $= e \times$ speed of approach $= 0.6\times6=3.6\ \text{m/s}$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'In an oblique impact between a smooth sphere and a fixed wall, the component of velocity parallel to the wall (tangential component) is:', '["Reduced to zero", "Doubled by the impact", "Unchanged by the impact", "Reversed by the impact"]'::jsonb, 2, 'A smooth (frictionless) surface exerts no force along the wall, so only the perpendicular (normal) component of velocity is affected; the tangential component is unaffected.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A smooth ball strikes a wall at $10\ \text{m/s}$ perpendicular to it, with coefficient of restitution $e=0.8$. Find its rebound speed.', '["$8\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$12.5\\ \\text{m/s}$", "$2\\ \\text{m/s}$"]'::jsonb, 0, 'Rebound speed $=e\times$ approach speed $=0.8\times10=8\ \text{m/s}$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a system of colliding bodies with no external force acting, which of these is always conserved, regardless of whether the collision is elastic or inelastic?', '["Individual velocities", "Individual kinetic energies", "Total momentum", "Total kinetic energy"]'::jsonb, 2, 'Momentum conservation holds for any collision with no external force; kinetic energy is only conserved in a perfectly elastic collision.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball of mass $5\ \text{kg}$ moving at $8\ \text{m/s}$ rebounds off a wall at $2\ \text{m/s}$ in the opposite direction. Find the magnitude of the impulse delivered by the wall.', '["$50\\ \\text{N·s}$", "$30\\ \\text{N·s}$", "$10\\ \\text{N·s}$", "$40\\ \\text{N·s}$"]'::jsonb, 0, 'Taking the initial direction as positive: $\Delta p = 5(-2)-5(8) = -10-40=-50$, so the impulse has magnitude $50\ \text{N·s}$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the magnitude of $\mathbf{a}=3\mathbf{i}+4\mathbf{k}$.', '["$5$", "$7$", "$25$", "$1$"]'::jsonb, 0, '$|\mathbf{a}|=\sqrt{3^2+4^2}=5$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A line makes angles $\alpha$, $\beta$, $\gamma$ with the $x$-, $y$- and $z$-axes. Its direction cosines are:', '["$(\\cos\\alpha, \\cos\\beta, \\cos\\gamma)$", "$(\\sin\\alpha, \\sin\\beta, \\sin\\gamma)$", "$(\\alpha, \\beta, \\gamma)$", "$(\\tan\\alpha, \\tan\\beta, \\tan\\gamma)$"]'::jsonb, 0, 'Direction cosines are, by definition, the cosines of the angles the line makes with each axis.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=2\mathbf{i}+3\mathbf{j}$ and $\mathbf{b}=-5\mathbf{i}+\mathbf{j}$, find $\mathbf{a}+\mathbf{b}$.', '["$7\\mathbf{i}+2\\mathbf{j}$", "$-3\\mathbf{i}+2\\mathbf{j}$", "$3\\mathbf{i}-4\\mathbf{j}$", "$-3\\mathbf{i}+4\\mathbf{j}$"]'::jsonb, 3, 'Adding components: $(2-5)\mathbf{i}+(3+1)\mathbf{j}=-3\mathbf{i}+4\mathbf{j}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The zero vector $\mathbf{0}$ is considered linearly dependent with any other vector because:', '["It has infinite magnitude in every possible direction", "It always points due north by mathematical convention", "It cannot ever be added to any other vector", "A non-trivial combination $c\\mathbf{0}=\\mathbf{0}$ holds for any $c\\ne0$"]'::jsonb, 3, 'Since $c\mathbf{0}=\mathbf{0}$ for any nonzero $c$, the zero vector always admits a non-trivial dependency relation.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=\mathbf{i}+\mathbf{j}+\mathbf{k}$ and $\mathbf{b}=2\mathbf{i}-\mathbf{j}-\mathbf{k}$, find $\mathbf{a}\cdot\mathbf{b}$.', '["$2$", "$4$", "$-2$", "$0$"]'::jsonb, 3, '$\mathbf{a}\cdot\mathbf{b}=(1)(2)+(1)(-1)+(1)(-1)=2-1-1=0$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The magnitude of $\mathbf{a}\times\mathbf{b}$ equals $|\mathbf{a}||\mathbf{b}|\sin\theta$, which represents the:', '["Length of the parallelogram''s longer diagonal", "Area of the parallelogram with sides $\\mathbf{a}$ and $\\mathbf{b}$", "Volume of the parallelepiped formed by three vectors", "Perimeter of the parallelogram with sides $\\mathbf{a}$ and $\\mathbf{b}$"]'::jsonb, 1, 'This is the standard geometric interpretation of the cross product''s magnitude.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t)=e^t\mathbf{i}+t^2\mathbf{j}$, find $d\mathbf{r}/dt$.', '["$te^t\\mathbf{i}+2\\mathbf{j}$", "$e^t\\mathbf{i}+t\\mathbf{j}$", "$e^t\\mathbf{i}+2t\\mathbf{j}$", "$e^t\\mathbf{i}+t^2\\mathbf{j}$"]'::jsonb, 2, '$d(e^t)/dt=e^t$ and $d(t^2)/dt=2t$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'If $\mathbf{a}(t)$ has constant magnitude, then $\mathbf{a}$ and $d\mathbf{a}/dt$ are always:', '["Both equal to zero", "Perpendicular to each other", "Parallel to each other", "Equal to each other"]'::jsonb, 1, 'Differentiating $\mathbf{a}\cdot\mathbf{a}=\text{const}$ gives $2\mathbf{a}\cdot d\mathbf{a}/dt=0$, so the two are perpendicular.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the line through $(2,1)$ and $(5,-3)$.', '["$-3/4$", "$-4/3$", "$4/3$", "$3/4$"]'::jsonb, 1, '$m=(-3-1)/(5-2)=-4/3$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The line $y=mx+c$ is parallel to the $x$-axis when:', '["$m=0$", "$c=0$", "$m$ is undefined", "$m=1$"]'::jsonb, 0, 'A horizontal line has zero gradient, $m=0$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the radius of the circle $(x-1)^2+(y+2)^2=49$.', '["$7$", "$49$", "$24.5$", "$14$"]'::jsonb, 0, 'Comparing with $(x-a)^2+(y-b)^2=r^2$ gives $r^2=49$, so $r=7$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A circle passes through the origin and has centre $(3,4)$. Find its radius.', '["$25$", "$7$", "$3.5$", "$5$"]'::jsonb, 3, '$r=\sqrt{3^2+4^2}=\sqrt{25}=5$, the distance from the centre to the origin.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the value of $a$ for the parabola $y^2=8x$.', '["$2$", "$8$", "$4$", "$16$"]'::jsonb, 0, 'Comparing $y^2=8x$ with $y^2=4ax$: $4a=8 \Rightarrow a=2$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the ellipse $\dfrac{x^2}{169}+\dfrac{y^2}{25}=1$, find the length of the major axis.', '["$13$", "$10$", "$169$", "$26$"]'::jsonb, 3, '$a^2=169 \Rightarrow a=13$, so the major axis has length $2a=26$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the tangent to $y=x^2-4x$ at $x=3$.', '["$6$", "$-6$", "$2$", "$-2$"]'::jsonb, 2, '$dy/dx=2x-4$; at $x=3$: $2(3)-4=2$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'At a point where a curve has a horizontal tangent, the normal to the curve is:', '["Vertical", "Horizontal", "At $45^{\\circ}$", "Undefined"]'::jsonb, 0, 'The normal is perpendicular to the tangent, so a horizontal tangent gives a vertical normal.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle starts from rest and accelerates at $4\ \text{m/s}^2$ for $6\ \text{s}$. Find its final velocity.', '["$48\\ \\text{m/s}$", "$24\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$1.5\\ \\text{m/s}$"]'::jsonb, 1, '$v=u+at=0+4(6)=24\ \text{m/s}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle''s velocity is given by $v=3t^2-6t$. Find its acceleration at $t=2$.', '["$18\\ \\text{m/s}^2$", "$6\\ \\text{m/s}^2$", "$0\\ \\text{m/s}^2$", "$12\\ \\text{m/s}^2$"]'::jsonb, 1, '$a=dv/dt=6t-6$; at $t=2$: $6(2)-6=6\ \text{m/s}^2$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle has position vector $\mathbf{r}=2t^2\mathbf{i}+3t\mathbf{j}$. Find its velocity at $t=1$.', '["$4\\mathbf{i}+0\\mathbf{j}$", "$1\\mathbf{i}+3\\mathbf{j}$", "$4\\mathbf{i}+3\\mathbf{j}$", "$2\\mathbf{i}+3\\mathbf{j}$"]'::jsonb, 2, '$\mathbf{v}=4t\mathbf{i}+3\mathbf{j}$; at $t=1$: $4\mathbf{i}+3\mathbf{j}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle moving in a plane has zero acceleration. Its velocity vector must therefore be:', '["Always perpendicular to its position vector", "Increasing steadily", "Constant, in both magnitude and direction", "Zero at all times"]'::jsonb, 2, 'Zero acceleration means the velocity vector does not change at all -- constant speed and direction, i.e. straight-line motion.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the force required to accelerate a $7\ \text{kg}$ mass at $2\ \text{m/s}^2$.', '["$3.5\\ \\text{N}$", "$5\\ \\text{N}$", "$14\\ \\text{N}$", "$9\\ \\text{N}$"]'::jsonb, 2, '$F=ma=7\times2=14\ \text{N}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body remains at rest under the action of several forces. This is an application of Newton''s:', '["First law", "Second law", "Third law", "Law of gravitation"]'::jsonb, 0, 'A body at rest (or moving at constant velocity) under balanced forces obeys Newton''s first law, the law of inertia.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball is thrown upward at $15\ \text{m/s}$. Taking $g=10\ \text{m/s}^2$, find the maximum height reached.', '["$1.5\\ \\text{m}$", "$150\\ \\text{m}$", "$11.25\\ \\text{m}$", "$22.5\\ \\text{m}$"]'::jsonb, 2, '$h=u^2/2g=225/20=11.25\ \text{m}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For a projectile launched at $\theta=30^{\circ}$ and one at $\theta=60^{\circ}$ with the same speed, the two ranges are:', '["Impossible to compare", "Equal, since $\\sin(60^{\\circ})=\\sin(120^{\\circ})$", "Different, with $60^{\\circ}$ always further", "Different, with $30^{\\circ}$ always further"]'::jsonb, 1, 'Since $R\propto\sin(2\theta)$ and $\sin(2\times30^{\circ})=\sin(60^{\circ})=\sin(120^{\circ})=\sin(2\times60^{\circ})$, complementary launch angles give equal ranges.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A simple pendulum has length $0.9\ \text{m}$. Taking $g=10\ \text{m/s}^2$, find its period to 2 decimal places.', '["$0.94\\ \\text{s}$", "$5.65\\ \\text{s}$", "$0.3\\ \\text{s}$", "$1.88\\ \\text{s}$"]'::jsonb, 3, '$T=2\pi\sqrt{\ell/g}=2\pi\sqrt{0.9/10}\approx1.88\ \text{s}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'The restoring force in an elastic string obeying Hooke''s law is proportional to the:', '["Square of its natural length", "Mass attached to it", "Extension beyond its natural length", "Total length of the string"]'::jsonb, 2, '$T=\lambda x/\ell_0$: the tension (and hence the restoring force) depends on the extension $x$, not the total length.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two identical smooth spheres collide head-on with equal and opposite velocities $u$ and $-u$, and $e=1$ (perfectly elastic). After impact, their velocities are:', '["Both equal to $u$", "Unchanged from before impact", "$-u$ and $u$ (they exchange velocities)", "Both zero"]'::jsonb, 2, 'For equal masses in a perfectly elastic head-on collision, the two bodies exactly exchange velocities.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Two bodies approach each other at $8\ \text{m/s}$ and $2\ \text{m/s}$ (in the same direction, the faster catching the slower). If $e=0.5$, find their speed of separation after impact.', '["$1\\ \\text{m/s}$", "$3\\ \\text{m/s}$", "$6\\ \\text{m/s}$", "$10\\ \\text{m/s}$"]'::jsonb, 1, 'Speed of approach $=8-2=6\ \text{m/s}$, so speed of separation $=e\times6=0.5\times6=3\ \text{m/s}$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector has direction cosines $l=0$, $m=0$, $n=1$. It points along the:', '["Line $y=x$", "$z$-axis", "$x$-axis", "$y$-axis"]'::jsonb, 1, 'With $l=m=0$ and $n=1$, the vector lies entirely along the $z$-axis.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the vector from $A(1,1,1)$ to $B(4,5,1)$.', '["$4\\mathbf{i}+5\\mathbf{j}+\\mathbf{k}$", "$3\\mathbf{i}+4\\mathbf{j}+2\\mathbf{k}$", "$3\\mathbf{i}+4\\mathbf{j}+0\\mathbf{k}$", "$5\\mathbf{i}+6\\mathbf{j}+2\\mathbf{k}$"]'::jsonb, 2, '$\overrightarrow{AB}=(4-1)\mathbf{i}+(5-1)\mathbf{j}+(1-1)\mathbf{k}=3\mathbf{i}+4\mathbf{j}$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=4\mathbf{i}-\mathbf{j}$, find $-3\mathbf{a}$.', '["$-3\\mathbf{i}+12\\mathbf{j}$", "$-12\\mathbf{i}+3\\mathbf{j}$", "$12\\mathbf{i}-3\\mathbf{j}$", "$-12\\mathbf{i}-3\\mathbf{j}$"]'::jsonb, 1, 'Multiplying each component by $-3$: $-12\mathbf{i}+3\mathbf{j}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Evaluate $(2\mathbf{i}) \times (3\mathbf{j})$.', '["$6\\mathbf{i}$", "$-6\\mathbf{k}$", "$6\\mathbf{k}$", "$5\\mathbf{k}$"]'::jsonb, 2, '$\mathbf{i}\times\mathbf{j}=\mathbf{k}$, so $(2\mathbf{i})\times(3\mathbf{j})=6(\mathbf{i}\times\mathbf{j})=6\mathbf{k}$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find $\int(4t^3\mathbf{i}+6t\mathbf{j})\,dt$ (ignoring the constant of integration).', '["$t^4\\mathbf{i}+6t^2\\mathbf{j}$", "$4t^4\\mathbf{i}+3t^2\\mathbf{j}$", "$t^4\\mathbf{i}+3t^2\\mathbf{j}$", "$12t^2\\mathbf{i}+6\\mathbf{j}$"]'::jsonb, 2, '$\int4t^3\,dt=t^4$ and $\int6t\,dt=3t^2$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the line with gradient $-2$ passing through $(1,5)$.', '["$y=-2x+5$", "$y=2x+5$", "$y=-2x-7$", "$y=-2x+7$"]'::jsonb, 3, '$y-5=-2(x-1) \Rightarrow y=-2x+2+5=-2x+7$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A circle has equation $x^2+y^2-4x-6y+4=0$. Find its centre.', '["$(2,-3)$", "$(2,3)$", "$(-2,-3)$", "$(4,6)$"]'::jsonb, 1, '$2g=-4, 2f=-6$, so centre $=(-g,-f)=(2,3)$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the parabola $x^2=4ay$, opening upward, find $a$ given the equation $x^2=20y$.', '["$10$", "$4$", "$5$", "$20$"]'::jsonb, 2, 'Comparing $x^2=20y$ with $x^2=4ay$: $4a=20 \Rightarrow a=5$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the normal to $y=x^2$ at $x=1$.', '["$2$", "$1/2$", "$-2$", "$-1/2$"]'::jsonb, 3, 'Tangent gradient $=2x=2$ at $x=1$; normal gradient $=-1/2$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle travels at constant velocity $10\ \text{m/s}$ for $5\ \text{s}$. Find the distance covered.', '["$2\\ \\text{m}$", "$5\\ \\text{m}$", "$50\\ \\text{m}$", "$15\\ \\text{m}$"]'::jsonb, 2, 'At constant velocity, $s=vt=10\times5=50\ \text{m}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle has velocity $\mathbf{v}=6\mathbf{i}-8\mathbf{j}$. Find its speed.', '["$2$", "$48$", "$10$", "$14$"]'::jsonb, 2, 'Speed $=\sqrt{6^2+8^2}=\sqrt{100}=10$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the acceleration produced by a $9\ \text{N}$ force on a $3\ \text{kg}$ mass.', '["$0.33\\ \\text{m/s}^2$", "$12\\ \\text{m/s}^2$", "$3\\ \\text{m/s}^2$", "$27\\ \\text{m/s}^2$"]'::jsonb, 2, '$a=F/m=9/3=3\ \text{m/s}^2$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball dropped from rest falls for $2\ \text{s}$. Taking $g=10\ \text{m/s}^2$, find its speed on landing.', '["$20\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$2\\ \\text{m/s}$", "$40\\ \\text{m/s}$"]'::jsonb, 0, '$v=gt=10\times2=20\ \text{m/s}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle in SHM has period $2\ \text{s}$. Find its angular frequency.', '["$0.5\\ \\text{rad/s}$", "$4\\pi\\ \\text{rad/s}$", "$\\pi\\ \\text{rad/s}$", "$2\\pi\\ \\text{rad/s}$"]'::jsonb, 2, '$\omega=2\pi/T=2\pi/2=\pi\ \text{rad/s}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball of mass $2\ \text{kg}$ moving at $5\ \text{m/s}$ is brought to rest by a constant force in $0.5\ \text{s}$. Find the magnitude of the impulse.', '["$1\\ \\text{N·s}$", "$10\\ \\text{N·s}$", "$2.5\\ \\text{N·s}$", "$20\\ \\text{N·s}$"]'::jsonb, 1, 'Impulse $=\Delta p = m(v-u) = 2(0-5) = -10$, so magnitude $10\ \text{N·s}$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A vector $\mathbf{a}$ has magnitude $6$ and direction cosine $l=1/2$ along the $x$-axis. Find its $x$-component.', '["$2$", "$3$", "$12$", "$6.5$"]'::jsonb, 1, '$x$-component $=|\mathbf{a}|l=6\times\tfrac{1}{2}=3$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=\mathbf{i}-\mathbf{j}$ and $\mathbf{b}=2\mathbf{i}+\mathbf{j}$, find $2\mathbf{a}+3\mathbf{b}$.', '["$8\\mathbf{i}-\\mathbf{j}$", "$2\\mathbf{i}+3\\mathbf{j}$", "$8\\mathbf{i}+\\mathbf{j}$", "$5\\mathbf{i}+2\\mathbf{j}$"]'::jsonb, 2, '$2\mathbf{a}=2\mathbf{i}-2\mathbf{j}$, $3\mathbf{b}=6\mathbf{i}+3\mathbf{j}$; sum $=8\mathbf{i}+\mathbf{j}$.', 'Addition of vectors, scalar multiplication and linear independence', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $|\mathbf{a}|=3$, $|\mathbf{b}|=4$ and the angle between them is $60^{\circ}$, find $\mathbf{a}\cdot\mathbf{b}$.', '["$6$", "$12$", "$3.46$", "$1$"]'::jsonb, 0, '$\mathbf{a}\cdot\mathbf{b}=|\mathbf{a}||\mathbf{b}|\cos\theta=3(4)(0.5)=6$.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{r}(t)=5\cos(2t)\mathbf{i}+5\sin(2t)\mathbf{j}$, find $d\mathbf{r}/dt$ at $t=0$.', '["$10\\mathbf{j}$", "$10\\mathbf{i}$", "$5\\mathbf{j}$", "$0$"]'::jsonb, 0, '$\mathbf{v}=-10\sin(2t)\mathbf{i}+10\cos(2t)\mathbf{j}$; at $t=0$: $10\mathbf{j}$.', 'Differentiation and integration of vectors with respect to a scalar', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the distance from the origin to the line $3x+4y=20$.', '["$4$", "$5$", "$20$", "$3$"]'::jsonb, 0, '$d=|3(0)+4(0)-20|/\sqrt{3^2+4^2}=20/5=4$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of a circle with centre $(0,0)$ and radius $6$.', '["$x^2+y^2=12$", "$x^2-y^2=36$", "$x^2+y^2=36$", "$x^2+y^2=6$"]'::jsonb, 2, '$(x-0)^2+(y-0)^2=6^2 \Rightarrow x^2+y^2=36$.', 'Coordinate geometry of the circle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'For the hyperbola $\dfrac{x^2}{9}-\dfrac{y^2}{16}=1$, find $a$ and $b$.', '["$a=3, b=16$", "$a=3, b=4$", "$a=9, b=16$", "$a=4, b=3$"]'::jsonb, 1, 'Comparing directly with the standard form: $a^2=9 \Rightarrow a=3$, $b^2=16 \Rightarrow b=4$.', 'Conic sections: parabola, ellipse and hyperbola', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent to $y=x^2$ at the point $(1,1)$.', '["$y=2x-1$", "$y=2x+1$", "$y=x$", "$y=2x$"]'::jsonb, 0, 'Gradient $=2x=2$ at $x=1$; $y-1=2(x-1) \Rightarrow y=2x-1$.', 'Tangents and normals', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle decelerates from $18\ \text{m/s}$ to rest over $3\ \text{s}$. Find its deceleration.', '["$6\\ \\text{m/s}^2$", "$54\\ \\text{m/s}^2$", "$0.17\\ \\text{m/s}^2$", "$21\\ \\text{m/s}^2$"]'::jsonb, 0, '$a=(v-u)/t=(0-18)/3=-6$, so deceleration is $6\ \text{m/s}^2$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle''s acceleration is $\mathbf{a}=2\mathbf{i}-3\mathbf{j}$, constant. Find its magnitude.', '["$6$", "$\\sqrt{13}$", "$5$", "$1$"]'::jsonb, 1, '$|\mathbf{a}|=\sqrt{2^2+3^2}=\sqrt{13}$.', 'Components of velocity and acceleration in a plane', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of momentum $40\ \text{kg·m/s}$ has mass $8\ \text{kg}$. Find its velocity.', '["$32\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$320\\ \\text{m/s}$", "$0.2\\ \\text{m/s}$"]'::jsonb, 1, '$v=p/m=40/8=5\ \text{m/s}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A projectile is launched horizontally at $12\ \text{m/s}$ from a height, taking $g=10\ \text{m/s}^2$. Find its vertical speed after $1\ \text{s}$.', '["$22\\ \\text{m/s}$", "$1.2\\ \\text{m/s}$", "$10\\ \\text{m/s}$", "$12\\ \\text{m/s}$"]'::jsonb, 2, 'Vertical motion starts from rest under gravity: $v=gt=10(1)=10\ \text{m/s}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A mass on a spring completes $10$ oscillations in $20\ \text{s}$. Find the period.', '["$200\\ \\text{s}$", "$2\\ \\text{s}$", "$0.5\\ \\text{s}$", "$10\\ \\text{s}$"]'::jsonb, 1, '$T=\text{total time}/\text{number of oscillations}=20/10=2\ \text{s}$.', 'Simple harmonic motion, elastic strings and the simple pendulum', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A ball approaches a wall at $9\ \text{m/s}$ and rebounds at $3\ \text{m/s}$. Find the coefficient of restitution.', '["$6$", "$1/3$", "$3$", "$27$"]'::jsonb, 1, '$e=\text{speed of separation}/\text{speed of approach}=3/9=1/3$.', 'Impulse, momentum and the impact of elastic bodies', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the magnitude of $\mathbf{a}=5\mathbf{i}-12\mathbf{j}$.', '["$13$", "$17$", "$7$", "$169$"]'::jsonb, 0, '$|\mathbf{a}|=\sqrt{5^2+12^2}=\sqrt{169}=13$.', 'Geometric representation of vectors, components and direction cosines', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Given $\mathbf{a}=2\mathbf{i}+3\mathbf{j}$ and $\mathbf{b}=-3\mathbf{i}+2\mathbf{j}$, find $\mathbf{a}\cdot\mathbf{b}$.', '["$13$", "$0$", "$6$", "$-6$"]'::jsonb, 1, '$\mathbf{a}\cdot\mathbf{b}=(2)(-3)+(3)(2)=-6+6=0$ -- perpendicular vectors.', 'Scalar and vector products of two vectors', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'Find the gradient of the line $4x-2y+3=0$.', '["$1/2$", "$2$", "$-2$", "$4$"]'::jsonb, 1, 'Rearranging: $2y=4x+3 \Rightarrow y=2x+3/2$, so gradient $=2$.', 'Two-dimensional coordinate geometry and the straight line', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A particle covers $100\ \text{m}$ in $8\ \text{s}$ at constant velocity. Find its speed.', '["$800\\ \\text{m/s}$", "$0.08\\ \\text{m/s}$", "$108\\ \\text{m/s}$", "$12.5\\ \\text{m/s}$"]'::jsonb, 3, '$v=s/t=100/8=12.5\ \text{m/s}$.', 'Kinematics of a particle', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of mass $2\ \text{kg}$ moves at $6\ \text{m/s}$. Find its kinetic energy, $\tfrac{1}{2}mv^2$.', '["$36\\ \\text{J}$", "$12\\ \\text{J}$", "$72\\ \\text{J}$", "$6\\ \\text{J}$"]'::jsonb, 0, '$KE=\tfrac{1}{2}(2)(6^2)=\tfrac{1}{2}(2)(36)=36\ \text{J}$.', 'Force, momentum and Newton''s laws of motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A stone is thrown vertically upward and returns to its starting point after $6\ \text{s}$. Taking $g=10\ \text{m/s}^2$, find its initial speed.', '["$15\\ \\text{m/s}$", "$6\\ \\text{m/s}$", "$30\\ \\text{m/s}$", "$60\\ \\text{m/s}$"]'::jsonb, 2, 'Total time of flight $=2u/g \Rightarrow 6=2u/10 \Rightarrow u=30\ \text{m/s}$.', 'Motion under gravity and projectile motion', false),
  ('mth-122-vectors-geometry-dynamics', 'MTH 122: Vectors, Coordinate Geometry & Elementary Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Social Sciences', 'Mathematics', '100 Level', 'A body of mass $4\ \text{kg}$ experiences an impulse of $20\ \text{N·s}$, starting from rest. Find its resulting velocity.', '["$0.2\\ \\text{m/s}$", "$16\\ \\text{m/s}$", "$5\\ \\text{m/s}$", "$80\\ \\text{m/s}$"]'::jsonb, 2, 'Impulse $=\Delta p=mv \Rightarrow 20=4v \Rightarrow v=5\ \text{m/s}$.', 'Impulse, momentum and the impact of elastic bodies', false);
